export function createPreviewCache(){
  let current;
  return {
    peek(key){return current?.key===key?current.blob:null;},
    prepare(key,build){
      if(current?.key===key)return current.promise;
      const entry={key,blob:null};current=entry;
      entry.promise=Promise.resolve().then(build).then(blob=>{entry.blob=blob;return blob;},error=>{if(current===entry)current=null;throw error;});
      return entry.promise;
    },
  };
}
