import {useEffect} from 'react';

// While any sheet, drum or dialog is open the page under it stays still.
// Safari ignores overflow alone for touch scrolling, so a touch move is cancelled unless a part of the overlay
// can itself scroll the way the finger goes: a list at its end, or a sheet with nothing to scroll, moves nothing.
// Fields keep their own moves, for selecting text.
let locks=0,saved=null,start=null;
const scrollable=/(auto|scroll)/;
function scrollsInside(target,dx,dy){
  const across=Math.abs(dx)>Math.abs(dy);
  for(let node=target;node&&node!==document.body;node=node.parentElement){
    const style=getComputedStyle(node);
    if(across&&scrollable.test(style.overflowX)&&node.scrollWidth>node.clientWidth+1&&(dx>0?node.scrollLeft>0:node.scrollLeft+node.clientWidth<node.scrollWidth-1))return true;
    if(!across&&scrollable.test(style.overflowY)&&node.scrollHeight>node.clientHeight+1&&(dy>0?node.scrollTop>0:node.scrollTop+node.clientHeight<node.scrollHeight-1))return true;
    // An overlay is fixed over the page; what scrolls outside it, the schedule under a drum included, is the page.
    if(style.position==='fixed')break;
  }
  return false;
}
const begin=event=>{const touch=event.touches?.[0];start=touch&&{x:touch.clientX,y:touch.clientY};};
const stray=event=>{
  if(event.touches?.length>1||event.target.closest?.('input,textarea,select'))return;
  const touch=event.touches?.[0];if(!touch||!start)return;
  if(!scrollsInside(event.target,touch.clientX-start.x,touch.clientY-start.y))event.preventDefault();
};
function lock(){
  if(locks++)return;
  const html=document.documentElement,body=document.body;
  saved={html:html.style.overflow,body:body.style.overflow,overscroll:html.style.overscrollBehavior};
  html.style.overflow='hidden';body.style.overflow='hidden';html.style.overscrollBehavior='none';
  document.addEventListener('touchstart',begin,{passive:true});
  document.addEventListener('touchmove',stray,{passive:false});
}
function unlock(){
  if(--locks)return;
  const html=document.documentElement,body=document.body;
  html.style.overflow=saved.html;body.style.overflow=saved.body;html.style.overscrollBehavior=saved.overscroll;
  document.removeEventListener('touchstart',begin);
  document.removeEventListener('touchmove',stray);
}
export default function useScrollLock(active=true){
  useEffect(()=>{if(!active)return;lock();return unlock;},[active]);
}
