// Dimensions are output pixels. Rendering uses a 2× pixel ratio.
export const validImageSize=value=>value&&typeof value.name==='string'&&Number.isInteger(value.width)&&Number.isInteger(value.height)&&value.width>=320&&value.width<=7680&&value.height>=320&&value.height<=7680;
export const logicalWidth=value=>Math.max(160,Math.min(3840,Number(value)||896));
export function applyImageSize(state,preset){return {...state,exportWidth:preset.width/2,exportHeight:preset.height/2};}
export function resizeImageWidth(state,pixels){const width=logicalWidth(pixels/2);return {...state,exportWidth:width,exportHeight:state.exportHeight?Math.round(state.exportHeight*width/logicalWidth(state.exportWidth)*2)/2:null};}
// Height alone: null goes back to the content's own height.
export function resizeImageHeight(state,pixels){return {...state,exportHeight:pixels==null?null:Math.max(160,Math.min(3840,Math.round(Number(pixels))/2))};}
const DEVICES=[['A4 · 300 ppi',2480,3508],['iPhone 17',1206,2622],['iPad Air 11″',1640,2360],['Android · Full HD+',1080,2400],['Full HD',1080,1920],['4K',2160,3840]];
export function defaultImageSizes(){return DEVICES.map(([name,width,height],index)=>({id:`sizes-${index}`,name,width,height,parentId:null}));}
// The first release laid the same devices out twice, upright in «Дни» and turned in «Недели». Those folders go:
// what was in them lies at the top, and a size that repeats another (same name and dimensions) is dropped.
const SEEDED_FOLDERS=new Set(['sizes-day','sizes-week']);
export function flattenImageSizes(entries){
  const seen=new Set();
  return entries.filter(entry=>!SEEDED_FOLDERS.has(entry.id)&&!/^sizes-week-\d+$/.test(entry.id))
    .map(entry=>SEEDED_FOLDERS.has(entry.parentId)?{...entry,parentId:null}:entry)
    .filter(entry=>{if(entry.kind==='folder')return true;const key=`${entry.name}|${entry.width}|${entry.height}`;if(seen.has(key))return false;seen.add(key);return true;});
}
export async function initializeImageSizes(storage){
  const version=storage.getItem('imageSizesVersion');if(version==='2')return;
  const current=JSON.parse(storage.getItem('sizeTemplates')||'[]');
  await storage.setItems({sizeTemplates:JSON.stringify(version?flattenImageSizes(current):[...current,...defaultImageSizes()]),imageSizesVersion:'2'});
}
// «По ширине текста»: the narrowest width at which no line of text has to wrap. The picture is laid out again
// off screen at its own max-content width; a picture as wide as half the page or more stretches with the page,
// so it does not count, while small pictures such as team logos keep their place.
export function textWidth(node){
  if(!node)return null;
  const width=node.offsetWidth,copy=node.cloneNode(true),host=document.createElement('div');
  host.style.cssText='position:fixed;left:-100000px;top:0;visibility:hidden;pointer-events:none;contain:layout';
  const sizes=[...node.querySelectorAll('img')].map(image=>image.offsetWidth);
  [...copy.querySelectorAll('img')].forEach((image,index)=>{const own=sizes[index];if(own>=width/2){image.style.width='0';image.style.minWidth='0';}else{image.style.width=`${own}px`;image.style.flex='none';}});
  [copy,copy.firstElementChild].filter(Boolean).forEach(element=>{element.style.width='max-content';element.style.height='auto';element.style.transform='none';});
  // Narrow-width layouts would answer to the measuring width itself, so the copy measures the full layout.
  copy.querySelectorAll('.i-sheet,.m-week-calendar,[data-id=schedule-view]').forEach(sheet=>{sheet.style.containerType='normal';});
  host.append(copy);(node.closest('.m-app')||document.body).append(host);
  // A little room to spare: the saved picture measures its text a hair differently from the page, and a line
  // that only just fits would wrap there while its box kept the height of one line.
  const result=Math.ceil(copy.getBoundingClientRect().width*1.02)+8;host.remove();
  return result;
}
