// An installed app keeps running from its cache. This notices a newer release on the site
// and switches to it only after every pending save has reached the browser storage.
// Schedules and templates live in IndexedDB, which an update never touches.

export function createAppUpdate({build,versionUrl,fetchVersion=url=>fetch(url,{cache:'no-store'}).then(response=>response.ok?response.json():null)}){
  let state={status:'idle',version:null};
  const listeners=new Set();
  const set=next=>{state={...state,...next};listeners.forEach(listener=>listener(state));};
  let checking=null;
  return {
    getSnapshot:()=>state,
    subscribe(listener){listeners.add(listener);return()=>listeners.delete(listener);},
    // quiet checks run in the background and only ever raise "ready"; a manual check also reports "current" or "offline".
    check({quiet=false}={}){
      if(checking||['ready','updating'].includes(state.status))return checking||Promise.resolve(state);
      if(!quiet)set({status:'checking'});
      checking=fetchVersion(versionUrl+'?t='+Date.now()).then(remote=>{
        if(remote?.build&&remote.build!==build)set({status:'ready',version:remote.version||null});
        else if(!quiet)set({status:remote?'current':'offline'});
      },()=>{if(!quiet)set({status:'offline'});}).finally(()=>{checking=null;});
      return checking.then(()=>state);
    },
    dismiss(){if(state.status!=='updating')set({status:'idle'});},
    async apply({storage,activate,reload}){
      set({status:'updating'});
      try{
        await waitForSaves(storage);
        await activate();
        reload();
      }catch(error){set({status:'ready',error:error.message});}
    },
  };
}

export function waitForSaves(storage,timeout=8000){
  return new Promise((resolve,reject)=>{
    let stop=()=>{};
    const timer=setTimeout(()=>{stop();reject(Error('Изменения ещё сохраняются. Попробуйте обновить через минуту.'));},timeout);
    const check=status=>{
      if(status.failed){clearTimeout(timer);stop();reject(Error('Есть несохранённые изменения. Нажмите «Повторить» внизу экрана, затем обновите.'));}
      else if(!status.pending){clearTimeout(timer);stop();resolve();}
    };
    stop=storage.subscribe(check)||stop;
    check(storage.getSnapshot());
  });
}

// Fetches the new service worker, lets it take over, and waits until it controls this page.
export async function activateServiceWorker(scriptUrl){
  if(!('serviceWorker' in navigator))return;
  // Without a worker (blocked, private mode) a plain reload still fetches the new page from the network.
  const registration=await navigator.serviceWorker.getRegistration(scriptUrl).then(found=>found||navigator.serviceWorker.register(scriptUrl)).catch(()=>null);
  if(!registration)return;
  await registration.update().catch(()=>{});
  const installing=registration.installing;
  if(installing)await new Promise(resolve=>{const done=()=>{if(['installed','activated','redundant'].includes(installing.state)){installing.removeEventListener('statechange',done);resolve();}};installing.addEventListener('statechange',done);done();});
  const waiting=registration.waiting;
  if(!waiting)return;
  await new Promise(resolve=>{
    const timer=setTimeout(resolve,4000);
    navigator.serviceWorker.addEventListener('controllerchange',()=>{clearTimeout(timer);resolve();},{once:true});
    waiting.postMessage('skip-waiting');
  });
}

const base=import.meta.env?.BASE_URL||'/';
export const SERVICE_WORKER_URL=base+'sw.js';
export const APP_VERSION=typeof __APP_VERSION__==='string'?__APP_VERSION__:'dev';
export const appUpdate=createAppUpdate({build:typeof __BUILD_ID__==='string'?__BUILD_ID__:'dev',versionUrl:base+'version.json'});
