export function downloadBlob(
  blob,
  filename = "schedule.jpg",
  environment = globalThis,
) {
  if (!blob || !blob.size)
    throw Error("Не удалось создать изображение. Попробуйте ещё раз.");
  const url = environment.URL.createObjectURL(blob);
  const anchor = environment.document.createElement("a");
  anchor.download = filename;
  anchor.href = url;
  environment.document.body.appendChild(anchor);
  try {
    anchor.click();
  } finally {
    anchor.remove();
    // Safari and slower devices may start reading the URL after click returns.
    environment.setTimeout(() => environment.URL.revokeObjectURL(url), 60000);
  }
}

function deadline(promise, milliseconds, message) {
  let timer;
  return Promise.race([
    promise,
    new Promise((_, reject) => {
      timer = setTimeout(() => reject(Error(message)), milliseconds);
    }),
  ]).finally(() => clearTimeout(timer));
}

export async function renderScheduleImage(source, options, render) {
  if (!source) throw Error("Расписание ещё не готово к сохранению.");
  const clone = source.cloneNode(true);
  clone.classList.add("cloned-for-rendering");
  const host = document.createElement("div");
  host.setAttribute('aria-hidden','true');
  host.style.cssText =
    "position:fixed;left:-100000px;top:0;pointer-events:none";
  // The source can be behind a modal; its export must not inherit inert/hidden state.
  clone.removeAttribute("inert");
  clone.removeAttribute("aria-hidden");
  if (options.withShadow) clone.style.border = "20px solid transparent";
  else
    clone
      .querySelector(".shadow-lg.sm\\:border")
      ?.classList.add("hide-border-on-print");
  clone.style.width = options.renderAsMobile
    ? "420px"
    : options.fitContent
      ? "max-content"
      : source.offsetWidth + "px";
  if (options.renderAsMobile) clone.classList.add("render-mobile-padding");
  clone
    .querySelectorAll('[data-no-print="true"]')
    .forEach((node) => node.remove());
  clone
    .querySelectorAll("[data-make-invisible]")
    .forEach((node) => (node.style.visibility = "hidden"));
  // Keep wrapping identical to editable text in the preview and the exported image.
  clone.querySelectorAll("textarea").forEach((node) => {
    node.textContent = node.value;
  });
  host.appendChild(clone);
  document.body.appendChild(host);
  try {
    if (document.fonts)
      await deadline(
        document.fonts.ready,
        10000,
        "Шрифты не загрузились. Повторите сохранение.",
      );
    await Promise.all(
      [...clone.querySelectorAll("img")].map(async (image) => {
        image.loading = "eager";
        if (!image.src.startsWith("data:")) {
          try {
            const response = await fetch(image.src, {
              signal: AbortSignal.timeout(15000),
            });
            if (!response.ok) throw Error("Image unavailable");
            const blob = await response.blob();
            image.src = await new Promise((resolve, reject) => {
              const reader = new FileReader();
              reader.onload = () => resolve(reader.result);
              reader.onerror = () => reject(reader.error);
              reader.readAsDataURL(blob);
            });
          } catch {
            throw Error(
              "Изображение недоступно для экспорта. Загрузите его с устройства и повторите сохранение.",
            );
          }
        }
        await deadline(
          image.decode(),
          15000,
          "Изображение не загрузилось. Загрузите его с устройства и повторите сохранение.",
        );
        if (!image.naturalWidth)
          throw Error("Не удалось загрузить изображение для экспорта.");
      }),
    );
    const blob = await deadline(
      render(clone, {
        pixelRatio: 2,
        ...(source.dataset.fixedSize==='true'?{width:source.offsetWidth,height:source.offsetHeight}:{}),
        type: options.type || 'image/jpeg',
        quality: .84,
        preferredFontFormat: 'woff2',
        backgroundColor: document.documentElement.classList.contains("dark")
          ? "#09090b"
          : "#ffffff",
        filter: (node) =>
          !(node instanceof HTMLElement) || node.dataset.noPrint !== "true",
      }),
      30000,
      "Создание изображения заняло слишком много времени. Попробуйте изображение меньшего размера.",
    );
    if (!blob?.size)
      throw Error("Не удалось создать изображение. Попробуйте ещё раз.");
    return blob;
  } finally {
    host.remove();
  }
}
