import React from 'react';
import {softHyphens} from '../services/hyphens.js';
import useStacked from './useStacked.js';
function TeamName({name}){return <span className="m-game-team-name">{name.split(/(\s+)/u).map((part,index)=>/\s/u.test(part)?part:<span className="m-game-name-word" key={index}>{softHyphens(part)}</span>)}</span>;}
export default function GameMatch({item,compact=false}){
  return <div className={`m-game-match ${compact?'is-compact':''}`}><div className="m-game-teams">{['homeTeam','awayTeam'].map((key,index)=><React.Fragment key={key}>{index>0&&<span className="m-game-versus">:</span>}<span className="m-game-team">{item[key]?.image&&<img draggable={false} src={item[key].image} alt=""/>}<TeamName name={item[key]?.name||`Команда ${index+1}`}/></span></React.Fragment>)}</div>{item.description&&<small>{item.description}</small>}</div>;
}
// Both teams in one run of text, the way an ordinary event shows its description.
// In the finished picture the teams stand apart by a colon, the way a match is written: «Арсенал : Зенит».
// With «outer» the logos stand on the outer sides, as on a scoreboard: before the first team, after the second.
export function GameLine({item,separator=' — ',outer=false}){
  return ['homeTeam','awayTeam'].map((key,index)=>{const logo=item[key]?.image&&<img draggable={false} src={item[key].image} alt=""/>,after=outer&&index===1;return <React.Fragment key={key}>{index>0&&separator}<span className={`m-game-line-team ${after?'is-after':''}`}>{!after&&logo}{item[key]?.name||`Команда ${index+1}`}{after&&logo}</span></React.Fragment>;});
}
// The teams of a match in the classic picture: logos on the outer sides while both teams share a line, both leading once
// the second has wrapped under the first.
export function PictureTeams({item}){const [ref,stacked]=useStacked();return <div ref={ref} className="m-game-line-teams"><GameLine item={item} separator={null} outer={!stacked}/></div>;}
