import React from 'react';
import {EVENT_COLORS,eventTime,localDate,pictureStyle,pictureSize} from '../services/editor.js';
import {scheduleRows} from '../services/rows.js';
import {calendarWeeks} from '../services/week.js';
import {softHyphens} from '../services/hyphens.js';
import './ios-result.css';
import useStacked from './useStacked.js';

// The finished pictures in the style of iPhone settings: a grey page, white rounded cards,
// rows divided by thin lines, the icon first in a tile of the event's colour, then the time in bold, then the text.

const NOT_EVENTS=['h1','h2','h3','comment','date','image'];
const isEvent=item=>!NOT_EVENTS.includes(item.type);
const format=(day,options)=>new Intl.DateTimeFormat('ru-RU',options).format(new Date(`${day}T12:00:00`));
const words=(item,languages)=>languages.filter(code=>item.translations?.[code]).map(code=>({code,text:item.translations[code]}));

// Beside the text in grey, or each language on its own grey line under it; the text-apart mode shows nothing here.
function Tr({item,languages,mode}){
  const lines=words(item,languages);if(!lines.length||mode==='text-block')return null;
  // Each language is marked as such, so the browser may hyphenate it by its own rules where our syllables find no break.
  const line=({code,text})=><span key={code} lang={code}>{softHyphens(text)}</span>;
  return mode==='inline'?<em className="i-tr is-inline"> {lines.map((entry,index)=><React.Fragment key={entry.code}>{index>0&&' / '}{line(entry)}</React.Fragment>)}</em>:<span className="i-tr">{lines.map(line)}</span>;
}
// An icon sits in a tile of the event's colour; an event without an icon gets no tile at all, and its colour,
// if it has one, runs as a thin bar down its left edge.
const colorOf=item=>EVENT_COLORS[item.color]?.[1];
const paint=item=>colorOf(item)&&!item.icon?{'--i-bar':EVENT_COLORS[item.color][2]}:undefined;
function Tile({item,Icon,small=false}){
  if(!item.icon)return small?null:<span className="i-tile-gap"/>;
  const color=colorOf(item);
  return <span className={`i-tile ${small?'is-small':''} ${color?'':'is-plain'}`} style={color?{background:color}:undefined}><Icon icon={item.icon}/></span>;
}
// A range reads «09:00 – 10:00»; when a column is narrow it breaks after its dash, never before it or inside a time.
const Time=({item,className})=>{const [start,end]=eventTime(item).split(' – ');return <b className={className}>{start}{end&&<>{' – '}{end}</>}</b>;};
// A title or a note may have an icon of its own: it stands before the first word, the size of the letters.
const Mark=({item,Icon})=>item.icon?<span className="i-mark" aria-hidden="true"><Icon icon={item.icon}/></span>:null;
// The colon between the teams is drawn by .i-teams only while they share a line; teams standing one under the other need none.
// A team without a logo of its own shows a plain grey shield in its place, so both teams of a match look alike.
const SHIELD=`data:image/svg+xml,${encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M12 2.5 4.5 5.3v5.9c0 4.7 3.1 8.6 7.5 10.3 4.4-1.7 7.5-5.6 7.5-10.3V5.3Z" fill="#c7c7cc"/></svg>')}`;
function Teams({item,hyphens=false,className,as:Tag='span'}){
  const name=text=>hyphens?softHyphens(text):text,[ref,stacked]=useStacked();
  // On one line the logos stand on the outer sides, as on a scoreboard: before the first team, after the second.
  // Teams one under the other both lead with their logo.
  return <Tag ref={ref} className={className}>{['homeTeam','awayTeam'].map((key,index)=>{const logo=<img src={item[key]?.image||SHIELD} alt="" draggable={false}/>,after=index===1&&!stacked;return <span key={key} className="i-team">{!after&&logo}<span>{name(item[key]?.name||`Команда ${index+1}`)}</span>{after&&logo}</span>;})}</Tag>;
}
// A picture fills its place on its chosen background, fitted the chosen way.
const Picture=({item,className})=><div className={className} data-size={pictureSize(item)} style={{backgroundColor:pictureStyle(item).backgroundColor}}>{item.image&&<img src={item.image} alt="" style={pictureStyle(item)}/>}</div>;

// A day: its date small and red over a large title, then cards of events with section titles and notes between them.
// Rows in a card share the page's columns (a subgrid), so times and texts stand under each other on the whole picture;
// events side by side in a group are each a compact cell instead: icon and time on top, the text under them.
function Row({item,Icon,languages,mode,columns,own=false}){
  if(item.type==='image')return <Picture item={item} className="i-row is-picture"/>;
  return <div className={`i-row ${own?'is-cell':''} ${paint(item)?'has-bar':''}`} data-type={item.type} style={paint(item)}>
    {(own?item.icon:columns.includes('tile'))&&<Tile item={item} Icon={Icon}/>}
    {(own?eventTime(item):columns.includes('time'))&&<Time item={item} className="i-time"/>}
    <span className="i-body">{item.type==='game'
      ?<><Teams item={item} hyphens className="i-teams"/>{item.description&&<small className="i-place">{softHyphens(item.description)}</small>}</>
      :<span className="i-text">{softHyphens(item.description||'')}</span>}<Tr item={item} languages={languages} mode={mode}/></span>
  </div>;
}
export function IosDay({items,Icon,print=false,languages=[],translationMode='block',textBlocks=[]}){
  // The head is the leading title and date (one of each, in any order) with a picture beside them.
  const groups=scheduleRows(items),head=[];
  // A picture given a square of its own place stays in the schedule where it was put.
  for(const group of groups){if(group.some(item=>!['h1','date','image'].includes(item.type)||item.type==='image'&&pictureSize(item))||group.some(item=>head.some(taken=>taken.type===item.type)))break;head.push(...group);}
  // A picture alone is no head: without a title or a date it stays in the schedule as a picture of its own.
  if(!head.some(item=>item.type!=='image'))head.length=0;
  const lead=groups.findIndex(group=>!group.every(item=>head.includes(item)));
  const events=items.filter(isEvent),tile=events.some(item=>item.icon),time=events.some(item=>eventTime(item));
  const columns=[tile&&'[tile] max-content',time&&'[time] max-content','[body] minmax(0,1fr)'].filter(Boolean).join(' ');
  const title=head.find(item=>item.type==='h1'),date=head.find(item=>item.type==='date'&&item.date),picture=head.find(item=>item.type==='image'&&item.image);
  const dateText=date&&(date.endDate&&date.endDate>localDate(date.date)?`${format(localDate(date.date),{day:'numeric',month:'long'})} – ${format(date.endDate,{day:'numeric',month:'long'})}`:format(localDate(date.date),{weekday:'long',day:'numeric',month:'long'}));
  const blocks=[];let card=null;
  for(const group of lead<0?[]:groups.slice(lead)){
    if(group.length===1&&!isEvent(group[0])){card=null;blocks.push(group[0]);continue;}
    if(!card){card={id:`card-${group[0].id}`,groups:[]};blocks.push(card);}card.groups.push(group);
  }
  const row=(item,own)=><Row key={item.id} item={item} Icon={Icon} languages={languages} mode={translationMode} columns={columns} own={own}/>;
  // A row of the schedule may put a title or a note beside events; there it keeps its look inside the card.
  const cell=item=>isEvent(item)||item.type==='image'?row(item,true):<div key={item.id} className="i-row is-text">{text(item)}</div>;
  const text=block=>{
      const tr=<Tr item={block} languages={languages} mode={translationMode==='inline'?'block':translationMode}/>;
      switch(block.type){
        case 'h1':return <h2 key={block.id} className="i-h1"><Mark item={block} Icon={Icon}/>{softHyphens(block.description||'')}{tr}</h2>;
        case 'h2':return <h2 key={block.id} className="i-h2"><Mark item={block} Icon={Icon}/>{softHyphens(block.description||'')}{tr}</h2>;
        case 'h3':return <h3 key={block.id} className="i-h3"><Mark item={block} Icon={Icon}/>{block.description}{tr}</h3>;
        case 'comment':return <p key={block.id} className="i-note"><Mark item={block} Icon={Icon}/>{softHyphens(block.description||'')}{tr}</p>;
        case 'date':return block.date?<h3 key={block.id} className="i-h3 is-date">{format(localDate(block.date),{weekday:'long',day:'numeric',month:'long'})}{block.description&&` · ${block.description}`}</h3>:null;
        case 'image':return <Picture key={block.id} item={block} className="i-picture"/>;
        default:return null;
      }
  };
  return <div className={`i-sheet i-day ${print?'is-print':''}`} lang="ru">
    {head.length>0&&<header className="i-head"><div>
      {(dateText||date?.description)&&<p className="i-eyebrow">{[dateText,date?.description].filter(Boolean).join(' · ')}</p>}
      {title&&<h1><Mark item={title} Icon={Icon}/>{softHyphens(title.description)}<Tr item={title} languages={languages} mode={translationMode==='inline'?'block':translationMode}/></h1>}
    </div>{picture&&<img className="i-head-picture" src={picture.image} alt="" style={pictureStyle(picture)}/>}</header>}
    <div className="i-flow" style={{gridTemplateColumns:columns}}>{blocks.map(block=>{
      if(block.groups)return <div key={block.id} className="i-card">{block.groups.map(group=>group.length>1?<div key={`row-${group[0].id}`} className="i-split">{group.map(cell)}</div>:row(group[0]))}</div>;
      return text(block);
    })}</div>
    {textBlocks.filter(block=>block.content).map(block=><section key={block.code} className="i-apart"><h3 className="i-h3">{block.title}</h3><div className="i-card"><p>{block.content}</p></div></section>)}
  </div>;
}

// A week: seven equal columns of white cards; in each, events one under another divided by thin lines.
const WEEKDAYS=['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'];
function WeekItem({item,Icon,languages,mode}){
  const tr=<Tr item={item} languages={languages} mode={mode==='inline'?'block':mode}/>;
  switch(item.type){
    case 'h1':case 'h2':case 'h3':return <div className={`i-witem i-wtitle is-${item.type}`}><Mark item={item} Icon={Icon}/>{softHyphens(item.description)}{tr}</div>;
    case 'comment':return <div className="i-witem i-wnote"><Mark item={item} Icon={Icon}/>{softHyphens(item.description)}{tr}</div>;
    case 'date':return <div className="i-witem i-wnote">{item.date&&format(localDate(item.date),{day:'numeric',month:'long'})}{item.description&&` · ${item.description}`}</div>;
    case 'image':return <div className="i-witem i-wpicture" data-size={pictureSize(item)}><Picture item={item} className="i-wpicture-box"/></div>;
    default:{
      const time=eventTime(item),line=(item.icon||time||item.type!=='game')&&<div className="i-wline"><Tile item={item} Icon={Icon} small/>{time?<Time item={item}/>:item.type!=='game'&&<span className="i-wtext">{softHyphens(item.description)}</span>}</div>;
      return <div className={`i-witem ${paint(item)?'has-bar':''}`} style={paint(item)} data-type={item.type}>{line}
        {item.type==='game'?<><Teams item={item} hyphens className="i-wteams" as="div"/>{item.description&&<small className="i-place">{softHyphens(item.description)}</small>}</>:time&&<div className="i-wtext">{softHyphens(item.description)}</div>}{tr}
      </div>;
    }
  }
}
export function IosWeek({state,Icon,print=false,languages=[],translationMode='block'}){
  const range=`${format(state.weekStart,{day:'numeric',month:'long'})} — ${format(state.weekEnd,{day:'numeric',month:'long'})} ${state.weekEnd.slice(0,4)}`;
  return <div className={`i-sheet i-week ${print?'is-print':''}`} lang="ru">
    <header className="i-head"><div><p className="i-eyebrow">{range}</p>{state.cardTitle&&<h1>{softHyphens(state.cardTitle)}</h1>}</div></header>
    <div className="i-week-grid">
      {WEEKDAYS.map((name,index)=><span key={name} className={`i-weekday ${index>4?'is-weekend':''}`}>{name}</span>)}
      {calendarWeeks(state.weekStart,state.weekEnd).flat().map((day,index)=>{
        if(!day)return <section key={`empty-${index}`} className="i-wday is-outside"/>;
        const items=state.schedule.filter(item=>item.dayKey===day),off=!!state.offDays?.[day];
        return <section key={day} className={`i-wday ${off?'is-off':''}`}>
          <header className="i-wday-head"><span className="i-wday-name">{WEEKDAYS[(new Date(`${day}T12:00:00`).getDay()+6)%7]}</span><b>{format(day,{day:'numeric'})}</b><small>{format(day,{month:'short'}).replace('.','')}</small>{off&&<span className="i-off">Выходной</span>}</header>
          {scheduleRows(items).map(group=>{const node=item=><WeekItem key={item.id} item={item} Icon={Icon} languages={languages} mode={translationMode}/>;
            return group.length>1?<div key={`row-${group[0].id}`} className="i-wsplit">{group.map(node)}</div>:node(group[0]);})}
        </section>;
      })}
    </div>
  </div>;
}
