export const EVENT_TYPES = {timed: 'Время', untimed: 'Без времени', range: 'Интервал', game: 'Игра', date: 'Дата', h1: 'Заголовок H1', h2: 'Заголовок H2', h3: 'Заголовок H3', comment: 'Комментарий', image: 'Картинка'};
// Each colour is a fill of one lightness, so dark text reads the same on any of them, and a strong shade of the same hue
// for what is too thin to carry a pale fill (the bar beside an event without an icon).
export const EVENT_COLORS = {red:['Красный','#f7c6c2','#e5484d'],orange:['Оранжевый','#fad3ad','#f08c2e'],yellow:['Жёлтый','#f7e4a3','#e2b203'],green:['Зелёный','#c4e5c9','#34a853'],blue:['Синий','#c2dcf6','#3b82f6'],purple:['Фиолетовый','#dccbf3','#8b5cf6'],gray:['Серый','#dfe1e5','#8e8e93']};
// A picture block has no icon: it has a background behind the picture and a way of fitting it into its box, as in other editors.
export const IMAGE_FITS = {contain:'Вписать',cover:'Заполнить',fill:'Растянуть',none:'По центру'};
export const IMAGE_BACKGROUNDS = {white:['Белый','#ffffff'],...EVENT_COLORS,black:['Чёрный','#1d1f24']};
// A picture is as wide as its place, or a square of its own size standing at the left, in the middle or at the right.
export const IMAGE_SIZES = {full:'Во всю ширину',left:'Квадрат слева',center:'Квадрат по центру',right:'Квадрат справа'};
// A translation is of the event's text: once the text is erased, a translation left from before is not shown.
export const withoutStaleTranslations = item => item.description?.trim()||!item.translations?item:{...item,translations:{}};
export const pictureSize = item => item.size!=='full'&&IMAGE_SIZES[item.size]?item.size:undefined;
export function pictureStyle(item){ return {objectFit:IMAGE_FITS[item.fit]?item.fit:'contain',backgroundColor:IMAGE_BACKGROUNDS[item.background]?.[1]||'transparent'}; }
// Icons no longer offered: «Видеоразбор» drew the same camera as «Камера», the others were not wanted. Events that
// already have one still draw it.
export const RETIRED_ICONS = ['video','bottle','dance','pistol','star'];
export const ICON_LABELS = {'football-field':'Футбольное поле',dumbbell:'Тренировка',passport:'Паспорт','plane-takeoff':'Вылет','plane-landing':'Прилёт',camera:'Камера',utensils:'Питание',bed:'Отдых',stadium:'Стадион',document:'Документ',home:'Дом',bus:'Автобус','soccer-ball':'Футбольный мяч',lock:'Замок',moon:'Луна',cake:'День рождения',shirt:'Форма',bag:'Баул',battery:'Батарейка',important:'Важно',dance:'Танцы',wine:'Бокал вина',laundry:'Стирка',trophy:'Кубок',whistle:'Свисток',medical:'Медицина',scale:'Весы напольные',balance:'Весы рыночные',clock:'Время',pin:'Место',video:'Видеоразбор',meeting:'Собрание',mic:'Интервью',coffee:'Кофе',pool:'Бассейн',bottle:'Вода',boot:'Бутсы',goal:'Ворота','penalty-area':'Штрафная',cone:'Конус',cards:'Карточки',money:'Зарплата',church:'Церковь',truck:'Грузовик',star:'Звезда',pistol:'Пистолет'};
export function gestureAxis(x,y){return Math.max(Math.abs(x),Math.abs(y))<8?null:Math.abs(x)>Math.abs(y)?'x':'y';}
export function swipeAction(x,width){const threshold=Math.min(120,Math.max(70,width*.28));return Math.abs(x)<threshold?null:x<0?'delete':'copy';}
export function swipeScheduleItem(items,id,action,newId){const index=items.findIndex(item=>item.id===id);if(index<0)return items;if(action==='delete')return items.filter(item=>item.id!==id);if(action!=='copy')return items;const copy={...structuredClone(items[index]),id:newId||crypto.randomUUID()};return [...items.slice(0,index+1),copy,...items.slice(index+1)];}
export const minutes = value => { const [h,m] = String(value || '09:00').split(':').map(Number); return h*60+m; };
export function addMinutes(value, delta) { const total=((minutes(value)+delta)%1440+1440)%1440; return `${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`; }
export function nextScheduleTime(items) { const last=items.filter(item=>['timed','range','game'].includes(item.type)&&item.time).at(-1); return last ? addMinutes(['range','game'].includes(last.type)?(last.endTime||addMinutes(last.time,60)):last.time,30) : '09:00'; }
export function eventTime(item) { if(['range','game'].includes(item.type)&&!item.time)return item.endTime||''; return ['range','game'].includes(item.type)?(item.endTime?`${item.time} – ${item.endTime}`:item.time):item.type==='timed'?item.time:''; }
export function changeEventType(item,type,items) { return {...item,type,time:['timed','range','game'].includes(type)?item.time||nextScheduleTime(items):item.time||'',...(['range','game'].includes(type)?{endTime:item.endTime||addMinutes(item.time||nextScheduleTime(items),60)}:{}),...(type==='date'?{date:item.date||localDate()}: {})}; }

// A plain event has no type of its own: it is timed, untimed or a range by how many times are filled.
export const TEXT_KINDS = {event:'Обычный', game:'Игра', date:'Дата', h1:'Заголовок H1', h2:'Заголовок H2', h3:'Заголовок H3', comment:'Комментарий', image:'Картинка'};
const PLAIN = ['timed','untimed','range'];
export const textKind = item => PLAIN.includes(item.type) ? 'event' : item.type;
const timedType = item => item.time && item.endTime ? 'range' : item.time ? 'timed' : 'untimed';
export function withTimes(item, patch) { const next={...item,...patch}; if(textKind(item)!=='event')return next; if(!next.time&&next.endTime){next.time=next.endTime;next.endTime='';} return {...next,type:timedType(next)}; }
export function setTextKind(item, kind, items) { return kind==='event' ? {...item,type:timedType(item)} : changeEventType(item,kind,items); }
// A date event always has its start; the end is optional and never before the start.
export function withDates(item, patch) { const next={...item,...patch}; if(!next.date)return item; const start=localDate(next.date); if(!next.endDate||next.endDate<=start){const {endDate,...rest}=next;return rest;} return next; }
export function localDate(value=new Date()) { const date=value instanceof Date?value:new Date(value); if(Number.isNaN(date.getTime()))return localDate(); return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`; }
export function moveScheduleItem(items,id,target) { const from=items.findIndex(item=>item.id===id); if(from<0||target<0||target>=items.length||target===from)return items; const result=[...items]; const [item]=result.splice(from,1);result.splice(target,0,item);return result; }
export function dropTarget(rects,id,center) { const others=rects.filter(rect=>rect.id!==id);const index=others.findIndex(rect=>center<rect.top+rect.height/2);return index<0?others.length:index; }
export async function shareScheduleImage(blob,title,environment=globalThis) {
  if(!blob?.size)throw Error('Изображение ещё не готово. Попробуйте снова.');
  const file=new environment.File([blob],'schedule.jpg',{type:'image/jpeg'});
  if(environment.navigator.share && environment.navigator.canShare?.({files:[file]})) {
    try { await environment.navigator.share({files:[file]});return 'shared'; }
    catch(error){if(error.name==='AbortError')return 'cancelled';if(!['NotAllowedError','SecurityError'].includes(error.name))throw error;}
  }
  return {blob,filename:file.name};
}

export function eventLabel(item){if(item.type==='image')return item.description||'Картинка';return item.type==='game'?[item.homeTeam?.name||'Команда 1',item.awayTeam?.name||'Команда 2'].join(' — '):item.description||'Новое событие';}
const teamKey=name=>String(name||'').trim().replace(/\s+/gu,' ').toLocaleLowerCase('ru').replaceAll('ё','е');
export function findTeam(teams,name){const key=teamKey(name);return key?teams.find(team=>team.kind!=='folder'&&teamKey(team.name)===key)||null:null;}
export function teamSuggestions(teams,name,limit=8){const key=teamKey(name);return teams.filter(team=>team.kind!=='folder'&&team.name&&teamKey(team.name)!==key&&teamKey(team.name).includes(key)).sort((a,b)=>teamKey(b.name).startsWith(key)-teamKey(a.name).startsWith(key)).slice(0,limit);}
// Typing a saved team's name brings its picture; a picture that came from a template leaves with a name that no longer matches.
export function typeTeamName(value={},name,teams){const team=findTeam(teams,name);if(team)return {name:team.name,image:team.image||null};return {...value,name,image:value.image&&teams.some(entry=>entry.image===value.image)?null:value.image||null};}
// Inline editing walks an event's parts in this order: type, start, end, icon, colour, text.
export function inlineFields(item){return ['type',...(item.type==='timed'?['time']:['range','game'].includes(item.type)?['time','endTime']:item.type==='date'?['date']:[]),'icon','color',...(item.type==='game'?['teams']:[]),'text'];}
export const INLINE_FIELD_LABELS={type:'Тип',time:'Начало',endTime:'Конец',date:'Дата',icon:'Иконка',color:'Цвет',teams:'Команды',text:'Текст'};
