import React,{useState} from 'react';
import CenteredModal,{SheetNav} from './CenteredModal.jsx';
import TeamFields from './TeamFields.jsx';
export default function TeamTemplateEditor({value,onChange,onClose,onSave,busy,folderControl}){
  const [reading,setReading]=useState(false);
  return <CenteredModal label="Шаблон команды" onClose={onClose} className="m-template-dialog"><form inert={busy} onSubmit={event=>{event.preventDefault();if(!reading)onSave();}}><SheetNav title="Команда" onCancel={onClose} disabled={busy||reading||!value.name?.trim()}/><div className="m-modal-body">{folderControl}<TeamFields value={value} onChange={onChange} onBusyChange={setReading}/></div></form></CenteredModal>;
}
