import React,{useEffect,useLayoutEffect,useRef,useState} from 'react';
import {createPortal} from 'react-dom';
import {TEXT_KINDS,EVENT_COLORS,IMAGE_FITS,IMAGE_BACKGROUNDS,IMAGE_SIZES,pictureSize,pictureStyle,ICON_LABELS,localDate,findTeam,textKind,withTimes,withDates,setTextKind,addMinutes,nextScheduleTime} from '../services/editor.js';
import WheelOverlay,{ChoiceOverlay} from './WheelOverlay.jsx';
import EditorIcon from './EditorIcon.jsx';
import CenteredModal,{SheetNav} from './CenteredModal.jsx';
import TeamFields from './TeamFields.jsx';
import {readPicture} from '../services/picture.js';
import {countIcon} from '../services/icon-usage.js';
import {commandSuggestions,iconWord,colorWord,hasCommands,scheduleDay} from '../services/commands.js';
import {richCommands} from './CommandText.jsx';

const pad=value=>String(value).padStart(2,'0');
const HOURS=Array.from({length:24},(_,hour)=>pad(hour));
const MINUTES=Array.from({length:60},(_,minute)=>pad(minute));
const SHORT_KINDS={event:'Обычный',game:'Игра',date:'Дата',h1:'H1',h2:'H2',h3:'H3',comment:'Коммент.',image:'Картинка'};
const EMPTY='––';
const shortDate=value=>value.split('-').reverse().slice(0,2).join('.');
// A tab of a group: its colour as a stripe, the kind on top, then its icon and what the picture will show of it.
export function RowTab({item,Icon}){
  const kind=textKind(item),text=item.type==='game'?[item.homeTeam?.name||'Команда 1',item.awayTeam?.name||'Команда 2'].join(' — '):item.type==='date'&&!item.description?shortDate(localDate(item.date)):item.description;
  const color=kind==='image'?IMAGE_BACKGROUNDS[item.background]?.[1]:EVENT_COLORS[item.color]?.[1];
  return <>{color&&<i className="m-row-tab-color" style={{background:color}} aria-hidden="true"/>}<small>{kind==='event'?[item.time,item.endTime].filter(Boolean).join('–')||'Событие':SHORT_KINDS[kind]}</small>{kind==='image'?(item.image?<img draggable={false} src={item.image} alt="" style={pictureStyle(item)}/>:<span className="m-placeholder">Нет картинки</span>):<span>{item.icon&&Icon&&<span className="m-row-tab-icon"><Icon icon={item.icon}/></span>}<span className="m-row-tab-text">{text||<span className="m-placeholder">Без текста</span>}</span></span>}</>;
}
const fit=node=>{if(node){node.style.height='auto';node.style.height=node.scrollHeight+'px';}};

// Every part of the event sits on the card itself: drums for type and time, a palette for icon and colour, text typed in place.
// A picture's size drawn small: a frame with the picture filling it, or a square at its side.
const SizeGlyph=({size})=><span className="m-size-glyph" data-size={size==='full'?undefined:size} aria-hidden="true"><i/></span>;

export default function InlineCard({item,items,editingText,onPatch,onBeginEdit,onText,onTextDone,Icon,iconNames,languages=[],translationFields=false,availableLanguages=[],teams=[],onSaveTeam,handle,aside=null}){
  const [wheel,setWheel]=useState(null),[field,setField]=useState('description'),[typing,setTyping]=useState(null),row=useRef(null);
  const [picking,setPicking]=useState(false),[newTeam,setNewTeam]=useState(null),[pendingNew,setPendingNew]=useState(false),[reading,setReading]=useState(false);
  const game=item.type==='game',kind=textKind(item),timeless=['h1','h2','h3','comment'].includes(kind);
  useLayoutEffect(()=>{row.current?.querySelectorAll('textarea').forEach(fit);},[item.description,item.translations,editingText]);
  // iOS keeps the keyboard up when the tap lands on something that cannot take focus, so a tap outside the text ends typing itself.
  const done=useRef(onTextDone);done.current=onTextDone;
  useEffect(()=>{if(!editingText)return;const outside=event=>{if(row.current?.contains(event.target)||event.target.closest?.('.m-wheel-overlay'))return;if(row.current?.contains(document.activeElement))document.activeElement.blur();done.current();};document.addEventListener('pointerdown',outside,true);return()=>document.removeEventListener('pointerdown',outside,true);},[editingText]);
  const open=field=>event=>{event.stopPropagation();onBeginEdit();setWheel({field,anchor:event.currentTarget.getBoundingClientRect()});};
  const face=text=>({value:text,label:text,content:text});
  // «––» on either drum clears that time; an empty time picks up a sensible hour, or :00, once the other drum moves.
  const setTime=(field,value)=>onPatch(withTimes(item,{[field]:value}));
  const timeColumns=field=>{const empty=!item[field],[hour,minute]=(item[field]||'').split(':'),base=(field==='endTime'&&item.time?addMinutes(item.time,60):nextScheduleTime(items)).split(':')[0];return [
    {label:'Часы',width:54,value:empty?EMPTY:hour,items:[EMPTY,...HOURS].map(face),onChange:next=>setTime(field,next===EMPTY?'':`${next}:${empty?'00':minute}`)},
    {label:'Минуты',width:54,value:empty?EMPTY:minute,items:[EMPTY,...MINUTES].map(face),onChange:next=>setTime(field,next===EMPTY?'':`${empty?base:hour}:${next}`)},
  ];};
  // Teams come from the team templates with their logos; a team typed in earlier stays on the drum.
  const teamFace=team=>({value:team.id,label:team.name,content:<span className="m-wheel-team">{team.image?<img draggable={false} src={team.image} alt=""/>:<span className="m-team-suggestion-blank"/>}<span>{team.name}</span></span>});
  const teamColumn=key=>{const listed=teams.filter(team=>team.kind!=='folder'&&team.name),current=item[key]?.name?findTeam(listed,item[key].name):null,own=item[key]?.name&&!current?[{...item[key],id:'own'}]:[];return [
    {label:key==='homeTeam'?'Команда 1':'Команда 2',width:236,value:pendingNew?'new':current?.id||(own.length?'own':'none'),items:[{value:'none',label:'Без команды',content:<span className="m-placeholder">Без команды</span>},...[...own,...listed].map(teamFace),{value:'new',label:'Новая команда',content:<span className="m-wheel-team is-new"><EditorIcon name="plus"/><span>Новая команда</span></span>}],onChange:id=>{if(id==='new'){setPendingNew(true);return;}setPendingNew(false);const team=[...own,...listed].find(entry=>entry.id===id);onPatch({[key]:team?{name:team.name,image:team.image||null}:{name:'',image:null}});}},
  ];};
  const columns=wheel&&{
    type:[{label:'Тип',width:150,value:kind,items:Object.entries(TEXT_KINDS).map(([value,label])=>({value,label})),onChange:next=>onPatch(setTextKind(item,next,items))}],
    size:[{label:'Размер',width:230,value:pictureSize(item)||'full',items:Object.entries(IMAGE_SIZES).map(([value,label])=>({value,label,content:<span className="m-size-face"><SizeGlyph size={value}/>{label}</span>})),onChange:size=>onPatch({size:size==='full'?undefined:size})}],
    fit:[{label:'Вставка',width:150,value:IMAGE_FITS[item.fit]?item.fit:'contain',items:Object.entries(IMAGE_FITS).map(([value,label])=>({value,label})),onChange:fit=>onPatch({fit})}],
    time:timeColumns('time'),endTime:timeColumns('endTime'),
    homeTeam:teamColumn('homeTeam'),awayTeam:teamColumn('awayTeam'),
  }[wheel.field];
  // Passing «Новая команда» on the drum does nothing; the drum closed on it opens a sheet for the name and picture.
  const closeWheel=()=>{if(pendingNew&&wheel)setNewTeam({key:wheel.field,value:{name:'',image:null},save:false});setPendingNew(false);setWheel(null);};
  const addTeam=event=>{event.preventDefault();const name=newTeam.value.name?.trim();if(!name||reading)return;const image=newTeam.value.image||null;onPatch({[newTeam.key]:{name,image}});if(newTeam.save)onSaveTeam?.({id:crypto.randomUUID(),parentId:null,name,image});setNewTeam(null);};
  // The sheet lies over the whole app, not inside the card, and the card's own gestures never see a touch on it.
  const stop=event=>event.stopPropagation();
  const teamSheet=newTeam&&createPortal(<div className="m-sheet-host" onPointerDown={stop} onClick={stop} onKeyDown={stop}><CenteredModal label="Новая команда" onClose={()=>setNewTeam(null)} className="m-template-dialog"><form onSubmit={addTeam}><SheetNav title="Новая команда" action="Готово" onCancel={()=>setNewTeam(null)} disabled={reading||!newTeam.value.name?.trim()}/><div className="m-modal-body">
    <TeamFields label={newTeam.key==='homeTeam'?'Команда 1':'Команда 2'} value={newTeam.value} teams={teams.filter(team=>team.kind!=='folder')} onBusyChange={setReading} onChange={value=>setNewTeam(current=>({...current,value}))}/>
    {onSaveTeam&&<div className="m-ai-group m-team-save"><label className="m-ai-row"><span className="m-ai-row-text"><span>Сохранить в шаблонах</span><small>Команда появится в шаблонах команд</small></span><span className="m-rule-toggle"><input type="checkbox" role="switch" checked={newTeam.save} onChange={event=>{const save=event.target.checked;setNewTeam(current=>({...current,save}));}}/></span></label></div>}
  </div></form></CenteredModal></div>,document.querySelector('.m-app')||document.body);
  const choices=wheel&&{
    icon:{label:'Иконка',value:item.icon??'none',items:[{value:'none',label:'Без иконки',content:<span className="m-wheel-none"/>},...iconNames.map(name=>({value:name,label:ICON_LABELS[name],content:<Icon icon={name}/>}))],onChange:icon=>{if(icon!=='none')countIcon(icon);onPatch({icon:icon==='none'?null:icon});}},
    background:{label:'Фон',value:item.background||'none',items:[{value:'none',label:'Без фона',content:<span className="m-wheel-swatch is-none"/>},...Object.entries(IMAGE_BACKGROUNDS).map(([value,[label,color]])=>({value,label,content:<span className="m-wheel-swatch" style={{background:color}}/>}))],onChange:background=>onPatch({background:background==='none'?undefined:background})},
    color:{label:'Цвет',value:item.color||'none',items:[{value:'none',label:'Без цвета',content:<span className="m-wheel-swatch is-none"/>},...Object.entries(EVENT_COLORS).map(([value,[label,color]])=>({value,label,content:<span className="m-wheel-swatch" style={{background:color}}/>}))],onChange:color=>onPatch({color:color==='none'?undefined:color})},
  }[wheel.field];
  // A date event's start and end are dates; the native picker opens over the cell.
  const dateCell=(field,caption)=>{const value=field==='date'?localDate(item.date):item.endDate||'';return <label key={field} className="m-inline-cell m-inline-date" data-field={field}><small>{caption}</small><span className="m-inline-value">{value?shortDate(value):'––.––'}</span><input data-no-drag type="date" aria-label={`${caption}: ${value||'не задано'}`} min={field==='endDate'?localDate(item.date):undefined} value={value} onFocus={onBeginEdit} onClick={event=>{try{event.currentTarget.showPicker?.();}catch{}}} onChange={event=>onPatch(withDates(item,{[field]:event.target.value}))}/></label>;};
  // Equal cells across the top of the card, each a large target with its caption; the text runs below.
  const cell=(field,caption,label,children)=><button type="button" className={`m-inline-cell ${wheel?.field===field?'is-editing':''}`} data-field={field} aria-label={label} aria-haspopup="listbox" onClick={open(field)}><small>{caption}</small><span className="m-inline-value">{children}</span></button>;
  // Moving between the halves of the text row keeps editing; leaving the row ends it.
  const leave=event=>{if(!row.current?.contains(event.relatedTarget))onTextDone();};
  const begin=next=>()=>{setField(next);onText();};
  const keys=event=>{if(event.key==='Escape')event.currentTarget.blur();};
  const translate=(language,value)=>onPatch({translations:{...item.translations,[language]:value},translationMeta:{...item.translationMeta,[language]:{source:item.description,manual:true}}});
  const languageName=code=>availableLanguages.find(entry=>entry.code===code)?.nativeName||code;
  // Commands such as {дата}: once a brace is typed, what may follow it is offered under the text; a tap puts it in
  // place of what was typed after the brace. {иконка and {цвет go on to offer icons and colours; a colour comes with
  // its closing {цвет} and the caret between them. A tap keeps the field focused, so the keyboard stays up on a phone.
  // A grey line under the text shows what the picture will say.
  const commandDay={day:item.dayKey||scheduleDay({schedule:items||[]})};
  const look=area=>{const caret=area.selectionStart,match=caret===area.selectionEnd&&/\{([^{}\n]{0,40})$/.exec(area.value.slice(0,caret));setTyping(match?{key:area.dataset.field,start:match.index,end:caret,query:match[1]}:null);};
  const offer=typing&&commandSuggestions(typing.query,iconNames);
  const complete=(text,back=0)=>{
    const area=row.current?.querySelector(`textarea[data-field="${typing.key}"]`);if(!area)return;
    const {start,end}=typing,space=start&&!/\s/.test(area.value[start-1])?' ':'',value=area.value.slice(0,start)+space+text+area.value.slice(end),caret=start+space.length+text.length-back;
    if(typing.key==='description')onPatch({description:value});else translate(typing.key,value);
    requestAnimationFrame(()=>{area.focus();area.setSelectionRange(caret,caret);look(area);});
  };
  const choose=entry=>offer.kind==='icons'?complete(`{иконка ${iconWord(entry)}}`):offer.kind==='colors'?complete(`{цвет ${colorWord(entry)}}{цвет}`,6)
    :['иконка','цвет'].includes(entry.name)?complete(`{${entry.name} `):complete(`{${entry.name}}`);
  // Each half is the same box whether it shows text or takes typing, so the card keeps its shape.
  const half=(key,label,value,placeholder,onInput)=>editingText
    ?<textarea key={key} data-no-drag data-field={key} autoFocus={field===key} onFocus={()=>setField(key)} onSelect={event=>look(event.target)} rows={1} className="m-inline-text" aria-label={label} placeholder={placeholder} value={value||''} onChange={event=>{fit(event.target);look(event.target);onInput(event.target.value);}} onBlur={event=>{setTyping(null);leave(event);}} onKeyDown={keys}/>
    :<button key={key} type="button" className="m-inline-text is-shown" aria-label={`${label}: ${value||'пусто'}`} onClick={begin(key)}>{value||<span className="m-placeholder">{placeholder}</span>}</button>;
  const team=(key,index)=><button key={key} type="button" className={`m-inline-text is-shown m-inline-team ${wheel?.field===key?'is-editing':''}`} aria-haspopup="listbox" aria-label={`Команда ${index+1}: ${item[key]?.name||'не выбрана'}`} onClick={open(key)}>{item[key]?.image&&<img draggable={false} src={item[key].image} alt=""/>}<span className="m-inline-team-name">{item[key]?.name||<span className="m-placeholder">{`Команда ${index+1}`}</span>}</span></button>;
  // A picture block is built like an event: its settings as captioned cells across the top, the picture below them,
  // shown on its background, in its size and the way it is fitted. A tap on the picture picks another one.
  const pick=async event=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;setPicking(true);try{onPatch({image:await readPicture(file)});}catch{}finally{setPicking(false);}};
  if(kind==='image')return <article data-type="image" className="m-card m-inline-card m-image-card">
    <div className="m-inline-body">
      <div className="m-inline-cells">
        {cell('size','Размер',`Размер: ${IMAGE_SIZES[pictureSize(item)||'full']}`,<SizeGlyph size={pictureSize(item)||'full'}/>)}
        {cell('fit','Вставка',`Вставка: ${IMAGE_FITS[item.fit]||IMAGE_FITS.contain}`,IMAGE_FITS[item.fit]||IMAGE_FITS.contain)}
        {cell('background','Фон',`Фон: ${IMAGE_BACKGROUNDS[item.background]?.[0]||'без фона'}`,<span className="m-wheel-swatch" style={{background:IMAGE_BACKGROUNDS[item.background]?.[1]}} data-empty={!item.background}/>)}
        {cell('type','Тип',`Тип: ${TEXT_KINDS[kind]}`,SHORT_KINDS[kind])}
      </div>
      <label className="m-image-pick" data-size={pictureSize(item)} aria-label={item.image?'Заменить картинку':'Выбрать картинку'} style={{backgroundColor:pictureSize(item)?undefined:pictureStyle(item).backgroundColor}}>
        {item.image?<img draggable={false} src={item.image} alt="" style={pictureStyle(item)}/>:<span className="m-image-empty"><EditorIcon name="image"/><span>{picking?'Загрузка…':'Выбрать картинку'}</span></span>}
        <input type="file" accept="image/*" onChange={pick} onClick={event=>event.stopPropagation()}/>
      </label>
    </div>
    {aside}{handle}
    {columns&&<WheelOverlay anchor={wheel.anchor} columns={columns} onClose={()=>setWheel(null)}/>}
    {choices&&<ChoiceOverlay anchor={wheel.anchor} {...choices} onClose={()=>setWheel(null)}/>}
  </article>;
  return <article data-type={item.type} className={`m-card m-inline-card ${editingText?'is-editing':''}`} style={{'--event-fill':EVENT_COLORS[item.color]?.[1]||'#fff'}}>
    <div className="m-inline-body">
      <div className="m-inline-cells">
        {cell('icon','Иконка','Иконка',item.icon?<Icon icon={item.icon}/>:<span className="m-wheel-none"/>)}
        {item.type==='date'
          ?<>{dateCell('date','Начало')}{dateCell('endDate','Конец')}</>
          :[['time','Начало'],['endTime','Конец']].map(([field,caption])=>timeless
            ?<span key={field} className="m-inline-cell is-off" aria-hidden="true"><small>{caption}</small><span className="m-inline-value">—</span></span>
            :<React.Fragment key={field}>{cell(field,caption,`${caption}: ${item[field]||'не задано'}`,item[field]||'—')}</React.Fragment>)}
        {cell('color','Цвет','Цвет',<span className="m-wheel-swatch" style={{background:EVENT_COLORS[item.color]?.[1]}} data-empty={!item.color}/>)}
        {cell('type','Тип',`Тип: ${TEXT_KINDS[kind]}`,SHORT_KINDS[kind])}
      </div>
      <div ref={row} className="m-inline-texts">
        {/* A game is just its two teams; everything else has its text and translations. */}
        {game?<div className="m-inline-split">{team('homeTeam',0)}{team('awayTeam',1)}</div>:<div className="m-inline-split">
          {/* With the translation fields hidden, a translated event says so with a small mark at the right of its text. */}
          {!translationFields&&languages.some(language=>item.translations?.[language]?.trim())
            ?<div className="m-inline-translated">{half('description','Название события',item.description,item.type==='date'?'Подпись к дате':'Новое событие',description=>onPatch({description}))}<span className="m-translated-mark" title="Есть перевод" aria-label="Есть перевод"><EditorIcon name="translate"/></span></div>
            :half('description','Название события',item.description,item.type==='date'?'Подпись к дате':'Новое событие',description=>onPatch({description}))}
          {translationFields&&languages.map(language=>half(language,`Перевод · ${languageName(language)}`,item.translations?.[language],languageName(language),value=>translate(language,value)))}
        </div>}
        {!game&&hasCommands(item.description)&&<small className="m-command-preview" aria-label="На картинке">{richCommands(item.description,commandDay,'ru',Icon)}</small>}
        {!game&&editingText&&offer?.items.length>0&&<div className={`m-commands is-${offer.kind}`} role="group" aria-label={offer.kind==='icons'?'Иконки':offer.kind==='colors'?'Цвета':'Команды'}>{offer.items.map(entry=>{
          const name=offer.kind==='commands'?entry.name:entry,label=offer.kind==='icons'?ICON_LABELS[entry]:offer.kind==='colors'?EVENT_COLORS[entry][0]:`{${entry.name}}`;
          return <button key={name} type="button" data-no-drag title={offer.kind==='commands'?`${entry.label}: ${entry.example}`:label} aria-label={label} onPointerDown={event=>event.preventDefault()} onClick={()=>choose(entry)}>
            {offer.kind==='icons'?<Icon icon={entry}/>:offer.kind==='colors'?<><span className="m-wheel-swatch" style={{background:EVENT_COLORS[entry][2]}}/>{label}</>:label}</button>;})}</div>}
      </div>
    </div>
    {aside}{handle}
    {columns&&<WheelOverlay anchor={wheel.anchor} columns={columns} onClose={closeWheel}/>}
    {choices&&<ChoiceOverlay anchor={wheel.anchor} {...choices} onClose={()=>setWheel(null)}/>}
    {teamSheet}
  </article>;
}
