import React,{useState} from 'react';
import CenteredModal,{SheetNav} from './CenteredModal.jsx';
import {appStorage} from '../services/storage.js';

const WORD='Сброс';
// Resetting removes everything the app keeps and starts it again as new. It asks for the word typed in, so it never happens by a slip.
export default function ResetSheet({onClose}){
  const [text,setText]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
  const ready=text.trim().toLowerCase()===WORD.toLowerCase();
  const reset=async event=>{event.preventDefault();if(!ready||busy)return;setBusy(true);setError('');try{await appStorage.clear();location.reload();}catch(failure){setBusy(false);setError(failure?.message||'Не удалось сбросить данные.');}};
  return <CenteredModal label="Сброс приложения" onClose={onClose} className="m-template-dialog"><form onSubmit={reset}>
    <SheetNav title="Сброс" action="Сбросить" onCancel={onClose} disabled={!ready||busy}/>
    <div className="m-modal-body m-reset-body">
      <p>Удалятся расписание, шаблоны, команды, переводы и настройки ИИ. Отменить это нельзя. Скачанная модель ИИ останется на устройстве.</p>
      <label className="m-reset-field"><span>Чтобы подтвердить, введите слово «{WORD}»</span><input autoComplete="off" autoCapitalize="sentences" enterKeyHint="done" placeholder={WORD} value={text} onChange={event=>setText(event.target.value)} aria-invalid={!!text&&!ready}/></label>
      {error&&<p role="alert" className="m-danger">{error}</p>}
    </div>
  </form></CenteredModal>;
}
