import React from 'react';
import EditorIcon from './EditorIcon.jsx';

// The one way back: pinned to the top, and named after the screen it returns to.
// Only screens below a bottom tab have it; the tabs themselves are reached from the bottom bar.
export default function BackBar({label,onBack}){
  return <header className="m-back-bar"><button type="button" className="m-back" aria-label={`Назад: ${label}`} onClick={onBack}><EditorIcon name="back"/><span>{label}</span></button></header>;
}
