import {useEffect,useRef} from 'react';

// A slider a finger can catch on an iPhone: Safari moves a range only from its small knob, so the whole strip takes the touch.
// A touch on the knob drags it from where it was caught; a touch beside it moves the knob under the finger.
// The value goes through the input's own «input» event, so onChange, the keyboard and screen readers work as on any range.
const KNOB=30;
const setValue=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;
export default function RangeSlider({className='',style,onPointerDown,...props}){
  const ref=useRef(null),drag=useRef(null);
  const min=Number(props.min??0),max=Number(props.max??100),step=Number(props.step??1),value=Number(props.value);
  // The knob's centre travels from half a knob in from the left end to half a knob in from the right one.
  const centre=(input,current)=>{const box=input.getBoundingClientRect();return box.left+KNOB/2+(current-min)/(max-min||1)*(box.width-KNOB);};
  const move=(input,x)=>{
    const box=input.getBoundingClientRect(),share=Math.min(1,Math.max(0,(x-drag.current.offset-box.left-KNOB/2)/(box.width-KNOB||1)));
    const next=Math.round((min+share*(max-min)-min)/step)*step+min;
    if(String(next)===input.value)return;
    setValue.call(input,String(next));input.dispatchEvent(new Event('input',{bubbles:true}));
  };
  // Safari's own knob would drag along with ours; a cancelled touch start leaves the strip to the pointer events below.
  useEffect(()=>{const input=ref.current,stop=event=>event.preventDefault();input.addEventListener('touchstart',stop,{passive:false});return()=>input.removeEventListener('touchstart',stop);},[]);
  return <input ref={ref} type="range" {...props} className={`m-range ${className}`} style={{...style,'--fill':`${(value-min)/(max-min||1)*100}%`}}
    onPointerDown={event=>{
      if(event.button)return;
      const input=event.currentTarget,from=centre(input,Number(input.value));
      event.preventDefault();input.focus({preventScroll:true});try{input.setPointerCapture(event.pointerId);}catch{/* a pointer already gone: the drag ends with it */}
      drag.current={id:event.pointerId,offset:Math.abs(event.clientX-from)<=KNOB/2+6?event.clientX-from:0};
      onPointerDown?.(event);move(input,event.clientX);
    }}
    onPointerMove={event=>{if(drag.current?.id===event.pointerId)move(event.currentTarget,event.clientX);}}
    onPointerUp={()=>{drag.current=null;}} onPointerCancel={()=>{drag.current=null;}}/>;
}
