// Browsers without a Russian hyphenation dictionary cut long words anywhere in a narrow column («Восстановлени-е»).
// Soft hyphens between syllables let them break as a person would: after a vowel before a consonant and a vowel (во-да),
// between two consonants that stand between vowels (тан-цы), after the first of three (Самар-ской), never leaving fewer than three letters on a side.
const VOWEL=/[аеёиоуыэюяaeiouy]/i,SIGN=/[ьъй]/i;
export function softHyphens(text=''){
  // A text with commands drawn in (an array of words and marks) has its words hyphenated already.
  if(typeof text!=='string')return text;
  return text.replace(/[A-Za-zА-Яа-яЁё]{7,}/g,word=>{
    let out='';for(let i=0;i<word.length;i++){
      const before=word[i-1],here=word[i],next=word[i+1];
      const cut=i>=3&&word.length-i>=3&&!SIGN.test(here)&&(VOWEL.test(before)&&!VOWEL.test(here)&&next&&VOWEL.test(next)||!VOWEL.test(before)&&!SIGN.test(before)&&!VOWEL.test(here)&&VOWEL.test(word[i-2]||'')&&next&&VOWEL.test(next)||SIGN.test(before)&&!VOWEL.test(here)
        ||!VOWEL.test(before)&&!SIGN.test(before)&&VOWEL.test(word[i-2]||'')&&!VOWEL.test(here)&&next&&!VOWEL.test(next)&&VOWEL.test(word[i+2]||''));
      out+=(cut?'\u00ad':'')+here;
    }
    return out;
  });
}
