import React,{useEffect,useRef,useState} from 'react';
import EditorIcon from './EditorIcon.jsx';
import useScrollLock from './useScrollLock.js';

// A tab's own menu, risen above the held tab as in Telegram. The finger that opened it can slide onto an item and let go;
// a later tap works too. A tap beside it only closes it.
// Rows: {key,label,icon,danger,onSelect} or a segmented row {key,stay,segments:[{key,label,active,disabled,onSelect}]}.
export default function TabMenu({anchor,pointerId,label,rows,onClose}){
  const panel=useRef(null),latest=useRef({rows,onClose});latest.current={rows,onClose};
  const [hover,setHover]=useState(null);
  useScrollLock();
  const actions=()=>latest.current.rows.flatMap(row=>row.segments||[row]);
  // A segment of a `stay` row (День/Неделя) switches in place and leaves the menu open; anything else closes it.
  const run=key=>{const stay=latest.current.rows.some(row=>row.stay&&row.segments.some(entry=>entry.key===key)),action=actions().find(entry=>entry.key===key);if(action?.disabled)return;if(!stay)latest.current.onClose();action?.onSelect();};
  useEffect(()=>{const key=event=>{if(event.key==='Escape'){event.preventDefault();latest.current.onClose();}};document.addEventListener('keydown',key);panel.current?.querySelector('[data-menu-item]')?.focus({preventScroll:true});return()=>document.removeEventListener('keydown',key);},[]);
  useEffect(()=>{
    if(pointerId==null)return;
    const under=event=>document.elementFromPoint(event.clientX,event.clientY)?.closest?.('[data-menu-item]')?.dataset.menuItem||null;
    const move=event=>{if(event.pointerId===pointerId)setHover(under(event));};
    const up=event=>{if(event.pointerId!==pointerId)return;stop();const key=under(event);if(key)run(key);setHover(null);};
    const stop=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);document.removeEventListener('pointercancel',stop);};
    document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);document.addEventListener('pointercancel',stop);return stop;
  },[pointerId]);
  // It rises above what was held, opens below it when there is no room above (a card near the top), and otherwise sits where it fits.
  const width=Math.min(280,window.innerWidth-24),left=Math.max(12,Math.min(window.innerWidth-width-12,anchor.left+anchor.width/2-width/2)),tall=rows.length*48+16,room=window.innerHeight-24;
  const below=anchor.top-20<tall&&window.innerHeight-anchor.top-anchor.height-20>=tall,place=anchor.top-20>=tall?{bottom:window.innerHeight-anchor.top+8}:below?{top:anchor.top+anchor.height+8}:{top:Math.max(12,window.innerHeight-tall-12),maxHeight:room,overflowY:'auto'};
  const item=entry=><button type="button" key={entry.key} role="menuitem" data-menu-item={entry.key} className={`m-tab-menu-item ${entry.danger?'m-danger':''} ${hover===entry.key?'is-hover':''}`} onClick={()=>run(entry.key)}><span>{entry.label}</span>{entry.icon&&<EditorIcon name={entry.icon}/>}</button>;
  return <div className="m-tab-menu-layer">
    <div className="m-tab-menu-shade" onPointerDown={event=>event.preventDefault()} onClick={()=>latest.current.onClose()} aria-hidden="true"/>
    <div ref={panel} role="menu" aria-label={label} className="m-tab-menu" style={{left,width,...place,transformOrigin:`${anchor.left+anchor.width/2-left}px ${place.bottom===undefined?'0':'100%'}`}}>
      {rows.map(row=>row.segments?<div key={row.key} role="group" aria-label={row.label} className="m-tab-menu-segments">{row.segments.map(segment=><button type="button" key={segment.key} role="menuitemradio" aria-checked={!!segment.active} data-menu-item={segment.key} disabled={segment.disabled} className={`${segment.active?'is-active':''} ${hover===segment.key?'is-hover':''}`} onClick={()=>run(segment.key)}>{segment.label}</button>)}</div>:item(row))}
    </div>
  </div>;
}
