// Commands in braces that a text keeps as written and the finished picture fills in: «Расписание на {дата}» is drawn
// «Расписание на 26 октября». The day is the schedule's own: in a week the day of the event, in a day the day of its
// first date card (a template puts the day it is loaded on there), and without a date card today.
// A translation may keep the Russian command or carry the English one; either is filled in the translation's language.
// Two commands take a word after them: {иконка автобус} draws the icon in the text, {цвет красный}…{цвет} paints what
// stands between them (a bare {цвет} with no colour open opens red).
import {addDays} from './week.js';
import {localDate,ICON_LABELS,EVENT_COLORS} from './editor.js';

export const COMMANDS=[
  {name:'дата',english:'date',label:'Дата дня',example:'26 октября'},
  {name:'день недели',english:'weekday',label:'День недели',example:'понедельник'},
  {name:'завтра',english:'tomorrow',label:'Дата следующего дня',example:'27 октября'},
  {name:'неделя',english:'week',label:'Даты недели',example:'26 октября – 1 ноября'},
  {name:'иконка',english:'icon',label:'Иконка в тексте',example:'{иконка автобус}'},
  {name:'цвет',english:'color',label:'Цветной текст',example:'{цвет красный}слово{цвет}'},
];
export const DATE_COMMANDS=['дата','завтра','неделя'];
const BY_NAME=new Map(COMMANDS.flatMap(command=>[[command.name,command],[command.english,command]]));
const key=text=>text.trim().toLocaleLowerCase('ru').replaceAll('ё','е').replace(/[\s_]+/g,' ');
// An icon or a colour is named by its Russian label, as the picker writes it, or by its English name.
const named=table=>new Map(Object.entries(table).flatMap(([name,label])=>[[key(name.replaceAll('-',' ')),name],[key(Array.isArray(label)?label[0]:label),name]]));
const ICONS=named(ICON_LABELS),COLORS=named(EVENT_COLORS);
export const iconWord=name=>key(ICON_LABELS[name]||name);
export const colorWord=name=>key(EVENT_COLORS[name]?.[0]||name);
const PATTERN=/\{([^{}\n]{1,40})\}/g;

const at=day=>new Date(`${day}T12:00:00`);
const format=(day,language,options)=>{try{return new Intl.DateTimeFormat(language,options).format(at(day));}catch{return new Intl.DateTimeFormat('ru-RU',options).format(at(day));}};
// A date is written the way the picture writes its date card: «26.10.2026» on the classic card, «понедельник, 26 октября»
// on an iPhone day, «26 октября» elsewhere. A narrow picture may break a numeric date after its month, never inside a number.
const date=(day,language,dates)=>dates==='numeric'?day.split('-').reverse().join('.').replace(/\.(\d{4})$/,'.​$1')
  :format(day,language,dates==='long'?{weekday:'long',day:'numeric',month:'long'}:{day:'numeric',month:'long'});
// The week a day stands in, Monday to Sunday; a week schedule gives its own first and last days.
function weekOf(day){const shift=(at(day).getDay()+6)%7;return [addDays(day,-shift),addDays(day,6-shift)];}
export function commandValue(name,{day,week,dates},language='ru'){
  switch(name){
    case 'дата':return date(day,language,dates);
    case 'день недели':return format(day,language,{weekday:'long'});
    case 'завтра':return date(addDays(day,1),language,dates);
    case 'неделя':{const [first,last]=week||weekOf(day),ends=dates==='long'?'short':dates;return `${date(first,language,ends)} – ${date(last,language,ends)}`;}
    default:return null;
  }
}
// What one pair of braces asks for, or null for braces that are only text.
function command(inner){
  const text=key(inner),simple=BY_NAME.get(text);
  if(simple)return simple.name==='цвет'?{color:null}:simple.name==='иконка'?null:{command:simple.name};
  const [, head,rest]=/^(\S+) (.+)$/.exec(text)||[];
  const kind=BY_NAME.get(head)?.name;
  if(kind==='иконка'&&ICONS.has(rest))return {icon:ICONS.get(rest)};
  if(kind==='цвет'&&COLORS.has(rest))return {color:COLORS.get(rest)};
  return null;
}
// The text as a tree: strings, {command}, {icon} and {color, children}. A colour left open runs to the end.
export function commandTree(text){
  const root=[],stack=[root];let from=0;
  const push=node=>stack.at(-1).push(node);
  for(const match of text.matchAll(PATTERN)){
    const found=command(match[1]);if(!found)continue;
    if(match.index>from)push(text.slice(from,match.index));from=match.index+match[0].length;
    if('color' in found){
      if(found.color===null&&stack.length>1){stack.pop();continue;}
      const node={color:found.color||'red',children:[]};push(node);stack.push(node.children);continue;
    }
    push(found);
  }
  if(from<text.length)push(text.slice(from));
  return root;
}
export const hasCommands=text=>typeof text==='string'&&[...text.matchAll(PATTERN)].some(match=>command(match[1]));
// The text with its commands as plain words: an icon has no word and drops out, a colour keeps its text.
export function fillCommands(text,context,language='ru'){
  if(!hasCommands(text))return text;
  const plain=nodes=>nodes.map(node=>typeof node==='string'?node:node.children?plain(node.children):node.icon?'':commandValue(node.command,context,language)).join('');
  return plain(commandTree(text)).replace(/ {2,}/g,' ');
}
// The day a day schedule is about: its first single date card, else today.
export function scheduleDay(state,today=new Date()){
  const card=(state.schedule||[]).find(item=>item.type==='date'&&item.date&&!item.endDate);
  return card?localDate(card.date):localDate(today);
}
// Every text of a schedule with its commands filled in, for drawing; the stored schedule keeps the commands.
// `fill` turns one text into what is drawn (plain words by default), `dates` is how the picture writes a date.
export function withCommands(state,{today=new Date(),dates,fill=fillCommands}={}){
  const weekly=state.scheduleMode==='week',week=weekly&&state.weekStart?[state.weekStart,state.weekEnd||addDays(state.weekStart,6)]:null;
  const dayOf=item=>weekly?(item.dayKey||state.weekStart||localDate(today)):scheduleDay(state,today);
  const item=entry=>{
    const context={day:dayOf(entry),week,dates};
    return {...entry,description:fill(entry.description,context),
      ...(entry.translations?{translations:Object.fromEntries(Object.entries(entry.translations).map(([code,value])=>[code,fill(value,context,code)]))}:{})};
  };
  const head={day:weekly?(state.weekStart||localDate(today)):scheduleDay(state,today),week,dates};
  return {...state,cardTitle:fill(state.cardTitle,head),schedule:(state.schedule||[]).map(item)};
}
// What to offer while a brace is being typed: the commands that start with what follows it, then, after
// «{иконка » or «{цвет », the icons or colours whose names hold the word typed so far.
export function commandSuggestions(query,icons=Object.keys(ICON_LABELS)){
  const typed=query.toLocaleLowerCase('ru').replaceAll('ё','е').replace(/\s+/g,' ').replace(/^ /,'');
  const [, head,rest='']=/^(\S+) (.*)$/.exec(typed)||[],kind=head&&BY_NAME.get(head)?.name,word=key(rest);
  if(kind==='иконка')return {kind:'icons',items:icons.filter(name=>!word||iconWord(name).includes(word)||name.includes(word))};
  if(kind==='цвет')return {kind:'colors',items:Object.keys(EVENT_COLORS).filter(name=>!word||colorWord(name).startsWith(word)||name.startsWith(word))};
  const start=key(typed);
  return {kind:'commands',items:COMMANDS.filter(entry=>entry.name.startsWith(start)||entry.english.startsWith(start))};
}
