// The looks a finished picture can take. They are made by us, not by the user; the user only picks one,
// separately for a day and for a week, and the classic look is the first choice of a new user.
export const PICTURE_STYLES=[
  {id:'classic',name:'Классика',note:'Привычный вид'},
  {id:'ios',name:'iOS',note:'Серый фон, белые карточки'},
  {id:'ios-print',name:'iOS для печати',note:'Белый фон, без лишней заливки'},
];
export const scheduleKind=state=>state?.scheduleMode==='week'?'week':'day';
export function pictureStyleFor(styles,kind){const id=styles?.[kind];return PICTURE_STYLES.some(style=>style.id===id)?id:'classic';}
export const validPictureStyles=value=>!!value&&typeof value==='object'&&!Array.isArray(value);
