// Whether the short notices after an action («Событие удалено», «Масштаб применён») show. A choice of this device,
// kept in localStorage; errors and questions show either way.
const KEY='multischedule-notices';
export function noticesOn(){try{return JSON.parse(localStorage.getItem(KEY))!==false;}catch{return true;}}
export function setNoticesOn(on){try{localStorage.setItem(KEY,JSON.stringify(!!on));}catch{/* private mode: notices just stay on */}}
