// How often each icon is picked, so the icon choice leads with the icons in use. It is a convenience of this device:
// kept in localStorage, never in the schedule or its undo history.
const USAGE_KEY='multischedule-icon-usage',ORDER_KEY='multischedule-icons-by-use';
const read=(key,fallback)=>{try{const value=JSON.parse(localStorage.getItem(key));return value??fallback;}catch{return fallback;}};
const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));}catch{/* private mode: the order just stays as drawn */}};

export const iconUsage=()=>read(USAGE_KEY,{});
export function countIcon(name){if(!name)return;const usage=iconUsage();write(USAGE_KEY,{...usage,[name]:(usage[name]||0)+1});}
// Before the first pick the icons already in the schedule stand for the habit.
export function startUsage(items=[]){const usage=iconUsage();if(Object.keys(usage).length)return usage;const counted={};for(const item of items)if(item.icon)counted[item.icon]=(counted[item.icon]||0)+1;return counted;}
export const iconsByUse=()=>read(ORDER_KEY,true)!==false;
export const setIconsByUse=on=>write(ORDER_KEY,!!on);
// The most picked first; ties and icons never picked keep the drawn order.
export const orderIcons=(names,usage)=>names.map((name,index)=>({name,index,count:usage[name]||0})).sort((a,b)=>b.count-a.count||a.index-b.index).map(entry=>entry.name);
