import React from 'react';
import {scheduleRows} from '../services/rows.js';
import {pictureSize} from '../services/editor.js';

// Events of one row stand side by side in the picture; everything else keeps its own line.
// A row of only a title and a date with one picture is a head: the texts one under the other, the picture beside them.
const isHead=group=>group.every(item=>['h1','date','image'].includes(item.type))&&group.filter(item=>item.type==='image').length===1&&!group.some(item=>item.type==='image'&&pictureSize(item));
export function sideBySide(items,nodes){
  let at=0;
  return scheduleRows(items).map(group=>{const part=nodes.slice(at,at+=group.length);return group.length>1?<div key={`row-${group[0].id}`} className={`m-export-row ${isHead(group)?'is-head':''}`}>{part}</div>:part[0];});
}
