import React,{useRef,useState} from 'react';
import CenteredModal,{SheetNav} from './CenteredModal.jsx';
import EventList from './EventList.jsx';
import ScheduleDays,{WeekDates} from './ScheduleDays.jsx';
import WeekStrip from './WeekStrip.jsx';
import EditorIcon from './EditorIcon.jsx';
import {swipeScheduleItem,nextScheduleTime} from '../services/editor.js';
import {moveApart,placeItem,normalizeRows,groupIds,removeItems,copyGroup} from '../services/rows.js';
import ConfirmDialog,{groupRequest} from './ConfirmDialog.jsx';
import {reorderSubset,dateRange,scheduleTitlePrefix,scheduleTitle} from '../services/week.js';
import {createScheduleItem} from '../services/schedule.js';

// A saved schedule is edited with the same cards as the schedule itself; a week also gets its pages and day strip.
export default function DayTemplateEditor({value,onChange,onClose,onSave,onApply,folderControl,applyLabel='Добавить в расписание',busy,Icon,iconNames,teams,languages,availableLanguages}){
  const [focused,setFocused]=useState(value.weekStart),[textId,setTextId]=useState(null),pages=useRef(null),strip=useRef(null);
  const weekly=value.scheduleMode==='week',days=dateRange(value.weekStart,value.weekEnd),focus=days.includes(focused)?focused:days[0];
  const update=patch=>onChange(current=>({...current,...patch}));
  // Swiped, a card is deleted or copied, or gets a new event on its right or left (in its own day of a week).
  // Deleting or copying an event of a group asks first whether it is that event alone or its whole group.
  const [question,setQuestion]=useState(null);
  const swipe=(id,action)=>{
    if(action==='delete'||action==='copy'){const target=value.schedule.find(item=>item.id===id),group=target?groupIds(value.schedule.filter(item=>item.dayKey===target.dayKey),id):[];
      if(group.length>1){setQuestion(groupRequest(action,group.length,{one:()=>change(id,action),all:()=>onChange(current=>({...current,schedule:action==='delete'?removeItems(current.schedule,group):copyGroup(current.schedule,group)}))}));return;}}
    change(id,action);
  };
  const change=(id,action)=>onChange(current=>{
    if(action!=='right'&&action!=='left')return {...current,schedule:normalizeRows(swipeScheduleItem(current.schedule,id,action))};
    const target=current.schedule.find(item=>item.id===id);if(!target)return current;
    const near=current.schedule.filter(item=>item.dayKey===target.dayKey),item=createScheduleItem({description:'',time:nextScheduleTime(near),...(target.dayKey?{dayKey:target.dayKey}:{})}),all=[...current.schedule,item];
    return {...current,schedule:target.dayKey?reorderSubset(all,all.filter(entry=>entry.dayKey===target.dayKey),item.id,{id,side:action},placeItem):placeItem(all,item.id,{id,side:action})};
  });
  const add=()=>{const event=createScheduleItem({description:'',time:nextScheduleTime(weekly?value.schedule.filter(item=>item.dayKey===focus):value.schedule),...(weekly?{dayKey:focus}:{})});onChange(current=>({...current,schedule:[...current.schedule,event]}));};
  const inline={textId,iconNames,languages,availableLanguages,teams,onBeginEdit:()=>{},onPatch:(id,patch)=>onChange(current=>({...current,schedule:current.schedule.map(item=>item.id===id?{...item,...patch}:item)})),onText:setTextId,onTextDone:()=>setTextId(null)};
  return <CenteredModal label="Редактирование шаблона расписания" onClose={onClose} className="m-template-dialog m-schedule-template-dialog"><form inert={busy} onSubmit={event=>{event.preventDefault();onSave();}}>
    <SheetNav title={weekly?'Шаблон недели':'Шаблон дня'} onCancel={onClose} disabled={busy}/><div className="m-modal-body">
      <label className="m-field">Название шаблона<input required value={value.name||''} onChange={event=>update({name:event.target.value})}/></label>
      {folderControl}
      {weekly?<>
        <label className="m-field">Заголовок недели<input value={scheduleTitlePrefix(value.cardTitle)} onChange={event=>update({cardTitle:scheduleTitle(event.target.value,value.scheduleMode)})}/></label>
        <WeekDates start={value.weekStart} end={value.weekEnd} onChange={update} off={!!value.offDays?.[focus]} onToggleOff={()=>onChange(current=>({...current,offDays:{...current.offDays,[focus]:!current.offDays?.[focus]}}))}/>
        <WeekStrip className="is-inline" trackRef={strip} onTrack={at=>pages.current?.track(at)} days={days} focus={focus} offDays={value.offDays} onSelect={setFocused}/>
        <ScheduleDays onToggleOff={day=>onChange(current=>({...current,offDays:{...current.offDays,[day]:!current.offDays?.[day]}}))} controllerRef={pages} onTrack={at=>strip.current?.track(at)} state={value} focus={focus} onFocus={setFocused} Icon={Icon} onMove={(day,id,target)=>onChange(current=>({...current,schedule:reorderSubset(current.schedule,current.schedule.filter(item=>item.dayKey===day),id,target,moveApart)}))} onPlace={(day,id,spot)=>onChange(current=>({...current,schedule:reorderSubset(current.schedule,current.schedule.filter(item=>item.dayKey===day),id,spot,placeItem)}))} onSwipe={swipe} enabled={!busy} inline={inline}/>
      </>:<EventList items={value.schedule} Icon={Icon} onMove={(id,target)=>onChange(current=>({...current,schedule:moveApart(current.schedule,id,target)}))} onPlace={(id,spot)=>onChange(current=>({...current,schedule:placeItem(current.schedule,id,spot)}))} onSwipe={swipe} enabled={!busy} inline={inline}/>}
      {/* A new event is added right under the events, saying what it does; saving and cancelling stay up in the bar. */}
      <button type="button" className="m-sheet-add" onClick={add}><EditorIcon name="plus"/>Добавить событие</button>
    </div>{onApply&&<div className="m-modal-footer"><button type="button" className="m-secondary m-sheet-apply" onClick={onApply}>{applyLabel}</button></div>}
  </form>{question&&<ConfirmDialog request={question} onClose={()=>setQuestion(null)}/>}</CenteredModal>;
}
