import {useEffect,useMemo,useRef,useState} from 'react';
import {createPreviewCache} from '../services/preview-cache.js';

export default function usePreviewImage({page,state,style,languages,translationMode,textBlocks,revision,sourceRef,render,onError}){
  const cache=useRef(null),latest=useRef({render,onError});latest.current={render,onError};if(!cache.current)cache.current=createPreviewCache();
  const key=useMemo(()=>({state,style,languages,translationMode,textBlocks,revision}),[state,style,languages,translationMode,textBlocks,revision]);
  const [image,setImage]=useState(null),[loading,setLoading]=useState(false);
  useEffect(()=>{
    if(page!=='save')return;let cancelled=false,secondFrame,idle,timer;const cached=cache.current.peek(key);
    if(cached){setImage({key,blob:cached});setLoading(false);return;}
    setLoading(true);
    const prepare=()=>{if(cancelled)return;cache.current.prepare(key,()=>latest.current.render(sourceRef.current)).then(blob=>{if(!cancelled)setImage({key,blob});},error=>{if(!cancelled)latest.current.onError(error);}).finally(()=>{if(!cancelled)setLoading(false);});};
    // Paint the preview first. Rasterization can start only after the next frame and an idle turn.
    const firstFrame=requestAnimationFrame(()=>{secondFrame=requestAnimationFrame(()=>{timer=setTimeout(()=>{if(window.requestIdleCallback)idle=window.requestIdleCallback(prepare,{timeout:700});else prepare();},180);});});
    return()=>{cancelled=true;cancelAnimationFrame(firstFrame);cancelAnimationFrame(secondFrame);if(idle!==undefined)window.cancelIdleCallback(idle);clearTimeout(timer);};
  },[page,key]);
  return {imageBlob:image?.key===key?image.blob:cache.current.peek(key),rendering:loading};
}
