import {useLayoutEffect,useRef,useState} from 'react';

// Whether the second child of a box has wrapped under the first. CSS cannot tell, so the box is measured again whenever
// its size changes (a wrap changes its height), and once the fonts have loaded: the observer waits for a drawn frame,
// which a page in the background or one being exported may never get, and the names grow wider in their real font.
export default function useStacked(){
  const ref=useRef(null),[stacked,setStacked]=useState(false);
  useLayoutEffect(()=>{
    const box=ref.current;if(!box)return;
    const measure=()=>{const [first,second]=box.children;if(!first||!second)return;setStacked(second.getBoundingClientRect().top>=first.getBoundingClientRect().bottom-1);};
    measure();const observer=new ResizeObserver(measure);observer.observe(box);
    let live=true;document.fonts?.ready.then(()=>live&&measure());
    return()=>{live=false;observer.disconnect();};
  },[]);
  return [ref,stacked];
}
