export function wheelAppearance(distance){
  const away=Math.min(3,Math.abs(distance));
  return {scale:Math.max(.64,1-away*.14),opacity:Math.max(.48,1-away*.19)};
}
export function hapticTick(){
  try{globalThis.navigator?.vibrate?.(7);}catch{/* Haptics are optional on browsers without support. */}
}
