import React from 'react';
import {folderOptions} from '../services/template-folders.js';

export default function FolderSelect({entries,value,onChange}){
  const options=folderOptions(entries);if(!options.length)return null;
  return <label className="m-field m-field-row">Папка<select value={value||''} onChange={event=>onChange(event.target.value||null)}><option value="">Вне папок</option>{options.map(option=><option key={option.id} value={option.id}>{option.label}</option>)}</select></label>;
}
