// Team names are names: in another language they are written in Latin letters, never translated («Факел» is Fakel, not Torch).
const LETTERS={а:'a',б:'b',в:'v',г:'g',д:'d',е:'e',ё:'yo',ж:'zh',з:'z',и:'i',й:'y',к:'k',л:'l',м:'m',н:'n',о:'o',п:'p',р:'r',с:'s',т:'t',у:'u',ф:'f',х:'kh',ц:'ts',ч:'ch',ш:'sh',щ:'shch',ъ:'',ы:'y',ь:'',э:'e',ю:'yu',я:'ya'};
const VOWELS='аеёиоуыэюяъь';
export function transliterate(text){
  let out='';
  for(let index=0;index<text.length;index++){
    const char=text[index],lower=char.toLowerCase(),before=text[index-1]?.toLowerCase();
    if(!(lower in LETTERS)){out+=char;continue;}
    // Е at the start of a word or after a vowel sounds «ye»: Енисей is Yenisey.
    let latin=lower==='е'&&(!before||!/[а-яё]/.test(before)||VOWELS.includes(before))?'ye':LETTERS[lower];
    if(char!==lower)latin=latin.charAt(0).toUpperCase()+latin.slice(1);
    out+=latin;
  }
  return out;
}
const CYRILLIC=/[А-Яа-яЁё]/;
// Only the endings a noun takes in its cases, so «Зенитом» is the team and «зенитный» is not.
const CASE_ENDINGS='ами|ями|ой|ей|ою|ею|ом|ем|ём|ам|ям|ах|ях|ов|ев|а|я|о|е|ё|у|ю|ы|и|й|ь';
const escape=text=>text.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
// Every Cyrillic team name of the roster and of the schedule's matches, longest first so «Динамо-2» wins over «Динамо».
export function teamNames(teams=[],items=[]){
  const names=[...teams.map(team=>team?.name),...items.flatMap(item=>item.type==='game'?[item.homeTeam?.name,item.awayTeam?.name]:[])];
  return [...new Set(names.map(name=>name?.trim()).filter(name=>name&&CYRILLIC.test(name)))].sort((a,b)=>b.length-a.length);
}
// A name in the text, in any case form («с Зенитом», «у Родины»), becomes its Latin spelling before translation,
// so neither the model nor the dictionary can turn it into a word.
export function protectTeams(text,names){
  let result=text;
  for(const name of names){
    const stem=name.replace(/[аеёиоуыэюяйь]$/i,'');if(stem.length<3)continue;
    const pattern=new RegExp(`(?<![А-Яа-яЁё])${escape(stem)}(?:${CASE_ENDINGS})?(?![А-Яа-яЁё])`,'g');
    result=result.replace(pattern,()=>transliterate(name));
  }
  return result;
}
export const matchLine=item=>['homeTeam','awayTeam'].map(key=>item[key]?.name?.trim()).filter(Boolean).map(transliterate).join(' : ');
