import React,{useEffect,useMemo,useRef,useState} from 'react';
import useEventDrag from './useEventDrag.js';
import EditorIcon from './EditorIcon.jsx';
import {scheduleRows} from '../services/rows.js';

// Own the gesture root so nested template editors cannot move the outer list.
const handle=<span data-drag-handle className="m-drag-handle" aria-hidden="true"><EditorIcon name="reorder"/></span>;
const ACTIONS={delete:['trash','Удалить'],copy:['copy','Копировать'],right:['arrow-right','Новое справа'],left:['arrow-left','Новое слева']};
const label=action=><span className="m-swipe-label"><EditorIcon name={ACTIONS[action][0]}/><span>{ACTIONS[action][1]}</span></span>;

// Which tab of a group was opened last outlives the list: leaving the «Расписание» page and coming back keeps it.
// Event ids are unique, so one shared memory serves every list.
let remembered=[];
const remember=list=>{remembered=list.slice(-300);return remembered;};

export default function GestureList({items,enabled=true,onMove,onSwipe,onDropInto,onPlace,onHold,swipeActions,tab,header,children,className=''}){
  const root=useRef(null),[recent,setRecentState]=useState(()=>remembered);
  const setRecent=change=>setRecentState(()=>remember(change(remembered)));
  const seen=id=>setRecent(list=>[...list.filter(entry=>entry!==id),id]);
  const drag=useEventDrag({root,items,enabled,onMove,onSwipe,onDropInto,onHold,swipeActions,onPlace:onPlace&&((id,spot)=>{seen(id);onPlace(id,spot);})});
  // A newly added event (created beside, copied, pasted from a template) opens in its row straight away.
  const known=useRef(null);
  useEffect(()=>{const ids=items.map(item=>item.id);if(known.current){const added=ids.filter(id=>!known.current.has(id));if(added.length)setRecent(list=>[...list.filter(id=>!added.includes(id)),...added]);}known.current=new Set(ids);},[items]);
  // Cards are built once per list change, so each drag frame only moves wrappers instead of re-rendering every card.
  const cards=useMemo(()=>new Map(items.map(item=>[item.id,children(item,handle)])),[items,children]);
  const card=item=>{
    const swiping=drag.view?.axis==='x'&&drag.view.id===item.id,revealed=!swiping&&drag.revealed?.id===item.id,side=swiping?drag.view.side:drag.revealed?.side;
    return <div key={item.id} data-event-id={item.id} data-drop-id={onPlace?item.id:undefined} className={`m-swipe-wrap ${swiping?'is-swiping':''} ${revealed?'is-revealed':''} ${drag.view?.into===item.id?'is-folder-target':''}`} style={drag.style(item.id,items.indexOf(item))}>
      {/* The uncovered actions wait for their own tap, like iOS lists; the one for the swipe's own side stands at the edge. */}
      {(swiping||revealed)&&<div className={`m-swipe-actions is-${side}`} aria-hidden={swiping||undefined}>{drag.sideActions(side).map(action=>revealed?<button key={action} type="button" data-swipe-action className={`m-swipe-hint is-${action}`} onClick={()=>drag.runRevealed(action)}>{label(action)}</button>:<span key={action} className={`m-swipe-hint is-${action}`}>{label(action)}</span>)}</div>}
      <div className="m-gesture-surface" style={drag.swipeStyle(item.id)}>{cards.get(item.id)}</div>
    </div>;
  };
  // A group (events standing side by side) shows its events as tabs in the order of the picture; the chosen one is edited at full width below them.
  const row=group=>{
    const open=group.reduce((best,item)=>recent.indexOf(item.id)>recent.indexOf(best.id)?item:best,group[0]);
    return <div key={`row-${group[0].id}`} className="m-row-block" data-drop-block={group.map(item=>item.id).join(' ')}>
      <div className="m-row-tabs" role="tablist" aria-label="Группа">{group.map(item=><button key={item.id} type="button" role="tab" aria-selected={item===open} data-drop-id={item.id} data-drop-tab className={`m-row-tab ${item===open?'is-open':''}`} onClick={()=>seen(item.id)}>{tab(item)}</button>)}</div>
      {card(open)}
    </div>;
  };
  return <div ref={root} className={`m-gesture-list ${className}`} data-folder-hover={drag.view?.into} data-dragging={drag.view?.axis==='y'?'':undefined} {...drag.handlers} onClickCapture={event=>{if(Date.now()<drag.suppressClick.current&&!event.target.closest('[data-swipe-action]')){event.preventDefault();event.stopPropagation();}}}>
    {header}
    {onPlace&&tab?scheduleRows(items).map(group=>group.length>1?row(group):card(group[0])):items.map(card)}
  </div>;
}
