import React from 'react';
import {commandTree,commandValue,hasCommands,DATE_COMMANDS} from '../services/commands.js';
import {EVENT_COLORS} from '../services/editor.js';
import {softHyphens} from '../services/hyphens.js';

// A text with commands as the picture draws it: a date in the look of the picture's own date card, an icon the size
// of the letters, a coloured run in the event colour's strong shade. A text without commands stays a plain string,
// so everything that drew it before draws it as before; its words, filled-in ones too, get soft hyphens.
export function richCommands(text,context,language,Icon){
  if(!hasCommands(text))return text;
  let key=0;
  const draw=nodes=>nodes.map(node=>{
    if(typeof node==='string')return softHyphens(node);
    if(node.children)return <span key={key++} className="cmd-color" style={{color:EVENT_COLORS[node.color]?.[2]}}>{draw(node.children)}</span>;
    if(node.icon)return <span key={key++} className="cmd-icon" aria-hidden="true">{Icon&&<Icon icon={node.icon}/>}</span>;
    const value=softHyphens(commandValue(node.command,context,language)||'');
    return DATE_COMMANDS.includes(node.command)?<span key={key++} className="cmd-date">{value}</span>:value;
  });
  return draw(commandTree(text));
}
