import {LOCAL_MODEL_CACHE} from './local-ai-tasks.js';

export function createLocalAiClient({createWorker,cacheStorage,origin}){
  let worker,pending,nextId=0,selectedDevice='auto';
  let state={phase:'idle',message:'Модель ещё не загружена',downloadedModel:false};
  const listeners=new Set();
  const update=patch=>{state={...state,...patch};for(const notify of listeners)notify(state);};
  const stop=(message='Остановлено')=>{
    worker?.terminate();worker=null;
    const current=pending;pending=null;
    update({phase:'idle',message,tokens:0});
    current?.reject(Object.assign(Error(message),{name:'AbortError',code:'LOCAL_AI_CANCELLED'}));
  };
  const request=(action,input={})=>{
    if(pending)return Promise.reject(Error('Дождитесь завершения текущей задачи или нажмите «Остановить».'));
    if(worker&&selectedDevice!==(input.device||'auto'))stop('Режим модели изменён');
    selectedDevice=input.device||'auto';
    return new Promise((resolve,reject)=>{
      const id=++nextId;
      pending={id,resolve,reject,started:performance.now()};
      update({phase:action==='prepare'?'loading':'generating',message:action==='prepare'?'Подготавливаем модель…':'Подготавливаем задачу…',tokens:0,downloaded:0,total:0,metrics:null});
      try{
        if(!worker){
          worker=createWorker();
          worker.onmessage=({data})=>{
            if(!pending||data.id!==pending.id)return;
            if(data.type==='progress'){const {id,type,...progress}=data;update(progress);return;}
            const current=pending;pending=null;
            if(data.type==='result'){update({phase:'ready',message:'Модель готова',tokens:0,metrics:data.metrics?{...data.metrics,totalMs:performance.now()-current.started}:null});current.resolve(data.result);}
            else{update({phase:'error',message:data.message});if(!data.recoverable){worker.terminate();worker=null;}current.reject(Object.assign(Error(data.message),{code:data.code||'LOCAL_AI_ERROR'}));}
          };
          worker.onerror=()=>{
            const current=pending;pending=null;worker?.terminate();worker=null;
            const message='Модель остановлена браузером. Возможно, недостаточно памяти. Попробуйте совместимый режим или Gemini.';
            update({phase:'error',message});current?.reject(Object.assign(Error(message),{code:'LOCAL_AI_ERROR'}));
          };
        }
        worker.postMessage({id,action,input});
      }catch(error){pending=null;worker?.terminate();worker=null;update({phase:'error',message:error.message});reject(error);}
    });
  };
  return {
    subscribe:listener=>{listeners.add(listener);return()=>listeners.delete(listener);},
    getSnapshot:()=>state,request,stop,
    async inspect(){
      try{
        if(!cacheStorage)return;
        const cache=await cacheStorage.open(LOCAL_MODEL_CACHE),entry=await cache.match(new URL('/__local-ai-ready',origin).href);
        if(entry&&state.phase==='idle')update({downloadedModel:true,message:'Модель сохранена на устройстве'});
      }catch{}
    },
    async remove(){stop('Модель удалена с устройства');await cacheStorage?.delete(LOCAL_MODEL_CACHE);update({downloadedModel:false});},
  };
}

export const localAi=createLocalAiClient({
  createWorker:()=>new Worker(new URL('./local-ai.worker.js',import.meta.url),{type:'module'}),
  cacheStorage:typeof caches==='undefined'?null:caches,origin:typeof location==='undefined'?'http://localhost':location.origin,
});
export const runLocalAi=(action,input)=>localAi.request(action,input);
