import React,{useEffect,useState} from 'react';
import GeminiSettings from './GeminiSettings.jsx';
import {aiProvider,LOCAL_MODEL} from '../services/local-ai-tasks.js';
import {localAi} from '../services/local-ai.js';
import {glossaryRules} from '../services/glossary.js';

export function useLocalAiStatus(){
  const [status,setStatus]=useState(localAi.getSnapshot);
  useEffect(()=>{const unsubscribe=localAi.subscribe(setStatus);localAi.inspect();return unsubscribe;},[]);
  return status;
}
export function LocalAiStatus({status}){
  const running=['loading','generating'].includes(status.phase);
  const seconds=value=>(value/1000).toLocaleString('ru',{minimumFractionDigits:1,maximumFractionDigits:1});
  return <div className="m-local-ai-status" role="status" aria-live="polite">
    <span>{status.message}{status.device?` · ${status.device==='webgpu'?'видеоускорение':'процессор'}`:''}</span>
    {status.phase==='loading'&&status.total>0&&<><progress aria-label="Загрузка модели" max={status.total} value={status.downloaded||0}/><small>{Math.round((status.downloaded||0)/1048576)} / {Math.round(status.total/1048576)} МБ</small></>}
    {status.metrics&&<small>{status.metrics.action==='translateText'?'Перевод':'Составление'}: {seconds(status.metrics.taskMs)} с · Всего: {seconds(status.metrics.totalMs)} с{status.metrics.prepareMs>1000?` · Подготовка: ${seconds(status.metrics.prepareMs)} с`:''}</small>}
    {running&&<button type="button" className="m-secondary" onClick={()=>localAi.stop()}>Остановить</button>}
  </div>;
}
export default function NeuralSettings({config,onChange,perform,busy,onDelete,status,templates,context}){
  const [benchmark,setBenchmark]=useState(null);
  const examples=[{id:'speed-1',text:'Завтрак'},{id:'speed-2',text:'Тренировка в зале'},{id:'speed-3',text:'Теория в конференц-зале'}];
  const local=aiProvider(config)==='local',running=['loading','generating'].includes(status.phase);
  const segment=(value,label,current,select)=><button type="button" role="radio" aria-checked={current===value} className={current===value?'is-active':''} disabled={busy||running} onClick={()=>current!==value&&perform(()=>select(value),null)}>{label}</button>;
  const measure=()=>perform(async()=>{const result=await localAi.request('translateText',{items:examples,targetLangs:['en'],glossary:glossaryRules(templates||[]),context:context||''});setBenchmark({result,metrics:localAi.getSnapshot().metrics});},null);
  // Where the AI works is a switch at the top; everything under it belongs to that choice.
  return <div className="m-ai-settings-page">
    <div className="m-ai-switch" role="radiogroup" aria-label="Где работает ИИ">{segment('gemini','Онлайн · Gemini',local?'local':'gemini',provider=>onChange({...config,provider}))}{segment('local','На устройстве',local?'local':'gemini',provider=>onChange({...config,provider}))}</div>
    {local?<>
      <p className="m-ai-note is-lead">Модель {LOCAL_MODEL.name.split(' · ')[0]}. Перевод и составление расписания прямо на устройстве, без ключа. Первая загрузка — около 650 МБ, потом работает без интернета. Если телефон умеет, модель сама включит видеоускорение, иначе работает на процессоре — медленнее, но так же.</p>
      <section className="m-ai-section">
        <h2>Модель на устройстве</h2>
        <div className="m-ai-group"><div className="m-ai-row is-static is-status"><LocalAiStatus status={status}/></div>
          {!running&&status.phase!=='ready'&&<button type="button" className="m-ai-row is-accent" onClick={()=>perform(async()=>{await navigator.storage?.persist?.();await localAi.request('prepare');},null)}>{status.downloadedModel?'Запустить':'Скачать модель'}</button>}
          {status.downloadedModel&&<button type="button" className="m-ai-row" disabled={busy||running} onClick={measure}>Проверить скорость</button>}
          {status.downloadedModel&&!running&&<button type="button" className="m-ai-row m-danger" onClick={()=>onDelete('Удалить локальную модель?','Освободится место на устройстве. Расписания и шаблоны сохранятся.',()=>localAi.remove())}>Удалить модель с устройства</button>}
        </div>
        {benchmark&&<div className="m-local-ai-benchmark"><p>Пробный перевод трёх событий на английский: {(benchmark.metrics.taskMs/1000).toLocaleString('ru',{maximumFractionDigits:1})} с, вместе с подготовкой {(benchmark.metrics.totalMs/1000).toLocaleString('ru',{maximumFractionDigits:1})} с.</p>{examples.map(item=><p key={item.id}>{item.text}<br/><strong>{benchmark.result[item.id].en}</strong></p>)}</div>}
      </section>
    </>:<GeminiSettings config={config} onChange={onChange} perform={perform} busy={busy} onDelete={onDelete}/>}
  </div>;
}
