import React,{useState} from 'react';
import CenteredModal from './CenteredModal.jsx';
import EditorIcon from './EditorIcon.jsx';
import {folderContents,isFolder,branchIds} from '../services/template-folders.js';
import {scheduleSnapshot,scheduleTemplateName} from '../services/week.js';

const countLabel=n=>`${n} ${n%100>=11&&n%100<=14?'событий':n%10===1?'событие':n%10>=2&&n%10<=4?'события':'событий'}`;
export const scheduleKind=entry=>entry.scheduleMode==='week'?'Неделя':'День';

// «Сохранить» keeps what is on screen in one tap; «Загрузить» lists every schedule, each marked as a day or a week.
export function saveScheduleNow({state,focusDay,onSaveSchedule,perform,onDone}){
  return perform(async()=>{if(await onSaveSchedule(scheduleTemplateName(state),null,scheduleSnapshot(state,state.scheduleMode==='week'?'week':'day',focusDay))!==false)onDone?.();},'Расписание сохранено в шаблоны');
}

export default function ScheduleTemplateMenu({state,focusDay,schedules,onSaveSchedule,onUseSchedule,onClose,perform,busy,initialMode=null}){
  const [mode,setMode]=useState(initialMode),[parentId,setParentId]=useState(null);
  const folder=schedules.find(entry=>entry.id===parentId&&isFolder(entry)),entries=folderContents(schedules,folder?.id||null);
  const back=()=>{if(folder)setParentId(folder.parentId||null);else if(initialMode)onClose();else setMode(null);};
  return <CenteredModal label="Шаблоны расписания" onClose={onClose} className="m-template-dialog m-scale-dialog m-template-browser"><header className="m-scale-heading">{mode&&<button type="button" className="m-icon-button" aria-label="Назад" onClick={back}><EditorIcon name="back"/></button>}<h2>{folder?folder.name:mode==='load'?'Загрузить шаблон':'Шаблоны'}</h2><button type="button" className="m-icon-button" aria-label="Закрыть шаблоны" onClick={onClose}><EditorIcon name="close"/></button></header>
    {!mode?<div className="m-modal-body"><button type="button" className="m-template-select" disabled={busy} onClick={()=>saveScheduleNow({state,focusDay,onSaveSchedule,perform,onDone:onClose})}><EditorIcon name="bookmark"/><span>Сохранить<small>{scheduleTemplateName(state)}</small></span></button><button type="button" className="m-template-select" onClick={()=>setMode('load')}><EditorIcon name="folder"/>Загрузить шаблон</button></div>
    :<div className="m-modal-body">{entries.length?entries.map(entry=><button type="button" key={entry.id} className="m-template-select" onClick={()=>isFolder(entry)?setParentId(entry.id):onUseSchedule(entry)}><EditorIcon name={isFolder(entry)?'folder':'schedule'}/><span>{entry.name||entry.cardTitle}<small>{isFolder(entry)?`Папка · ${branchIds(schedules,entry.id).size-1}`:`${scheduleKind(entry)} · ${countLabel(entry.schedule?.length||0)}`}</small></span></button>):<p className="m-template-target">Шаблонов расписаний пока нет. Сохраните текущее расписание — оно появится здесь.</p>}</div>}
  </CenteredModal>;
}
