import React,{useRef,useState} from 'react';
import {gestureAxis} from '../services/editor.js';
import EditorIcon from './EditorIcon.jsx';

export default function ActionDock({disabled,canUndo,canRedo,onUndo,onRedo,onCreate,onClear,onSave,label='Добавить событие'}){
  const root=useRef(null),gesture=useRef(null),suppress=useRef(0),[drag,setDrag]=useState(null);
  const end=commit=>{const current=gesture.current;gesture.current=null;setDrag(null);if(!current)return;try{current.node.releasePointerCapture(current.pointerId);}catch{}if(!current.axis)return;suppress.current=Date.now()+400;if(commit&&current.axis==='x'){if(current.target==='clear')onClear?.();if(current.target==='save')onSave?.();}};
  const side=(side,icon,text,available,action)=>{const supported=side==='clear'?onClear:onSave,active=drag&&supported;return <button type="button" className={`m-icon-button m-dock-side ${active?'is-target':''} ${drag?.target===side?'is-armed':''} ${side==='clear'?'is-clear':'is-save'}`} disabled={disabled||(!active&&!available)} aria-label={active?text:side==='clear'?'Отменить последнее изменение':'Вернуть отменённое изменение'} onClick={active?undefined:action}><EditorIcon name={active?(side==='clear'?'trash':'bookmark'):icon}/>{active&&<span>{text}</span>}</button>;};
  const progress=drag?.progress||0,style=drag?{width:drag.width,transform:`translateX(calc(-50% + ${drag.dx}px))`,opacity:1-Math.pow(progress,4),borderRadius:18+progress*2}:undefined;
  return <div ref={root} className={`m-bottom-actions m-add-row ${drag?'is-choosing':''}`} inert={disabled}>
    {side('clear','undo','Очистить',canUndo,onUndo)}<div className="m-dock-origin">
    <button type="button" className="m-icon-button m-add" aria-label={label} aria-description={onClear?'Перетащите влево к «Очистить».'+(onSave?' Вправо — «Шаблон».':''):undefined} disabled={disabled} style={style}
      onPointerDown={event=>{if((!onClear&&!onSave)||disabled||event.isPrimary===false||event.button!==0)return;const buttons=root.current.querySelectorAll('.m-dock-side'),left=buttons[0].getBoundingClientRect(),right=buttons[1].getBoundingClientRect(),center=event.currentTarget.getBoundingClientRect();gesture.current={node:event.currentTarget,pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,axis:null,target:null,left,right,center};event.currentTarget.setPointerCapture(event.pointerId);}}
      onPointerMove={event=>{const current=gesture.current;if(!current||event.pointerId!==current.pointerId)return;const delta=event.clientX-current.startX;if(!current.axis)current.axis=gestureAxis(delta,event.clientY-current.startY);if(current.axis!=='x')return;event.preventDefault();const left=current.left.left+current.left.width/2,right=current.right.left+current.right.width/2,center=current.center.left+current.center.width/2,direction=delta<0?'clear':'save',supported=direction==='clear'?onClear:onSave,target=direction==='clear'?left:right,distance=target-center,dx=Math.sign(delta)*Math.min(Math.abs(delta),Math.abs(distance)),progress=supported&&distance?Math.abs(dx/distance):0,rect=direction==='clear'?current.left:current.right;current.target=supported&&progress>.72&&event.clientX>=rect.left-12&&event.clientX<=rect.right+12&&event.clientY>=rect.top-18&&event.clientY<=rect.bottom+18?direction:null;setDrag({dx,progress,target:current.target,width:current.center.width+(rect.width-current.center.width)*progress*progress});}}
      onPointerUp={()=>end(true)} onPointerCancel={()=>end(false)} onClick={()=>{if(Date.now()>=suppress.current)onCreate();}}
    ><EditorIcon name="plus"/></button></div>{side('save','redo','Шаблон',canRedo,onRedo)}
  </div>;
}
