import { addMinutes } from './editor.js';
import { ARSENAL_CREST } from './arsenal-crest.js';

export function createScheduleItem(
  preset = {},
  now = new Date(),
  id = crypto.randomUUID(),
) {
  const type = preset.type || "timed";
  return {
    ...preset,
    id,
    type,
    time:
      ["timed", "range", "game"].includes(type)
        ? (preset.time ??
          now.toLocaleTimeString("ru-RU", {
            hour: "2-digit",
            minute: "2-digit",
          }))
        : "",
    description:
      preset.description ?? (type === "date" ? "Новая дата" : "Новое событие"),
    icon: preset.icon === undefined ? 'football-field' : preset.icon,
    ...(['range','game'].includes(type) ? {endTime:preset.endTime || addMinutes(preset.time || now.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}),60)} : {}),
    ...(type === "date" ? { date: preset.date || now.toISOString() } : {}),
  };
}

export function createTemplate(name, state, display, id = crypto.randomUUID()) {
  return structuredClone({ id, name, ...state, ...display });
}
// The schedule template everyone starts with: one group across the top, «Расписание на» as H1, the date beside it and the Arsenal crest on the right.
// A picture set in the template stays in it; the date is always the day the template is loaded on.
export const STANDARD_TEMPLATE_ID = 'standard', STANDARD_TEMPLATE_NAME = 'Стандартный день';
export function standardTemplate(now = new Date()) {
  const row = crypto.randomUUID();
  return createTemplate(STANDARD_TEMPLATE_NAME, {
    parentId: null, scheduleMode: 'day', titleInSchedule: true, cardTitle: 'Расписание',
    schedule: [
      { id: crypto.randomUUID(), type: 'h1', time: '', description: 'Расписание на', icon: null, row },
      { id: crypto.randomUUID(), type: 'date', time: '', description: '', icon: null, date: now.toISOString(), row },
      { id: crypto.randomUUID(), type: 'image', time: '', description: '', icon: null, image: ARSENAL_CREST, row },
    ],
  }, { translationDisplayMode: 'block', selectedLanguages: [], textBlockTranslations: {} }, STANDARD_TEMPLATE_ID);
}
// Added once to the saved templates; deleted later, it does not come back. Its first name, «Стандартный», becomes the current one unless renamed by hand.
export function withStandardTemplate(templates, seeded) {
  if (templates.some(template => template.id === STANDARD_TEMPLATE_ID && template.name === 'Стандартный')) return templates.map(template => template.id === STANDARD_TEMPLATE_ID ? { ...template, name: STANDARD_TEMPLATE_NAME } : template);
  return seeded || templates.some(template => template.id === STANDARD_TEMPLATE_ID) ? templates : [standardTemplate(), ...templates];
}
// Once, for templates saved before the crest: an empty picture slot of the standard template gets it.
// A picture chosen by hand stays; a crest removed later does not come back.
export function withStandardCrest(templates) {
  let changed = false;
  const next = templates.map(template => {
    if (template.id !== STANDARD_TEMPLATE_ID || !Array.isArray(template.schedule)) return template;
    const schedule = template.schedule.map(item => item.type === 'image' && !item.image ? (changed = true, { ...item, image: ARSENAL_CREST }) : item);
    return changed ? { ...template, schedule } : template;
  });
  return changed ? next : templates;
}
export function applyEventTemplate(item,template){
  const {id,parentId,dayKey,...data}=structuredClone(template);
  return {...data,id:item.id,...(item.dayKey?{dayKey:item.dayKey}:{})};
}

export function sameEventTemplate(left,right){
  const fields=['type','time','endTime','color','icon','date'];
  if(['homeTeam','awayTeam'].some(key=>JSON.stringify(left[key]||null)!==JSON.stringify(right[key]||null)))return false;
  if((left.description||'').trim().toLocaleLowerCase('ru')!==(right.description||'').trim().toLocaleLowerCase('ru'))return false;
  if(fields.some(field=>(left[field]??null)!==(right[field]??null)))return false;
  const languages=new Set([...Object.keys(left.translations||{}),...Object.keys(right.translations||{})]);
  return [...languages].every(language=>(left.translations?.[language]||'')===(right.translations?.[language]||''));
}
